INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_001', 'Chapter 1 : Introduction to Computer Systems', 'OP', 50, '[]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_002', 'Chapter 2 : Processing and Memory Management', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"Which coding system was developed by IBM primarily for mainframes?","answer":"B) EBCDIC","options":["A) ASCII","B) EBCDIC","C) Unicode","D) Hexadecimal"]},{"numb":2,"type":"Multiple Choices","question":"What is the primary difference between machine language and high-level programming languages?","answer":"A) Machine language is binary, while high-level languages use English-like syntax.","options":["A) Machine language is binary, while high-level languages use English-like syntax.","B) Machine language is easier to write.","C) High-level languages are slower.","D) High-level languages require no translation."]},{"numb":3,"type":"Multiple Choices","question":"How many colors can a 24-bit graphic image represent?","answer":"C) 16.7 million colors","options":["A) 16 colors","B) 256 colors","C) 16.7 million colors","D) 32 colors"]},{"numb":4,"type":"Multiple Choices","question":"Which of the following is a compressed audio file format?","answer":"B) MP3","options":["A) WAV","B) MP3","C) BMP","D) PNG"]},{"numb":5,"type":"Multiple Choices","question":"What does the acronym ALU stand for?","answer":"A) Arithmetic and Logic Unit","options":["A) Arithmetic and Logic Unit","B) Application Level Unit","C) Advanced Logic Utility","D) Asynchronous Logic Unit"]},{"numb":6,"type":"Multiple Choices","question":"What is the term for converting data into digital form so that it can be understood by a computer?","answer":"D) Digital Data Representation","options":["A) Encoding","B) Formatting","C) Rendering","D) Digital Data Representation"]},{"numb":7,"type":"Multiple Choices","question":"Which component of the CPU tries to retrieve data and instructions before they are needed?","answer":"D) Prefetch Unit","options":["A) ALU","B) FPU","C) Control Unit","D) Prefetch Unit"]},{"numb":8,"type":"Multiple Choices","question":"Which of the following file formats is typically used for still images?","answer":"A) GIF","options":["A) GIF","B) WAV","C) MP4","D) DOC"]},{"numb":9,"type":"Multiple Choices","question":"Which type of memory is used to permanently store firmware?","answer":"B) ROM","options":["A) RAM","B) ROM","C) Cache","D) Registers"]},{"numb":10,"type":"Multiple Choices","question":"What is the smallest unit of data in a binary computer system?","answer":"C) Bit","options":["A) Byte","B) Nibble","C) Bit","D) Word"]},{"numb":11,"type":"Multiple Choices","question":"Which of the following refers to the computer''s main memory?","answer":"B) RAM","options":["A) ROM","B) RAM","C) Cache","D) Flash Memory"]},{"numb":12,"type":"Multiple Choices","question":"What does CPU stand for?","answer":"C) Central Processing Unit","options":["A) Control Processing Unit","B) Computer Processing Unit","C) Central Processing Unit","D) Central Power Unit"]},{"numb":13,"type":"Multiple Choices","question":"Which of the following is a system of encoding used by most computers to represent text?","answer":"A) ASCII","options":["A) ASCII","B) Unicode","C) EBCDIC","D) Binary"]},{"numb":14,"type":"Multiple Choices","question":"What is the full form of SSD?","answer":"C) Solid State Drive","options":["A) System Storage Drive","B) Secure Storage Device","C) Solid State Drive","D) Synchronous Storage Disk"]},{"numb":15,"type":"Multiple Choices","question":"Which of the following is volatile memory?","answer":"A) RAM","options":["A) RAM","B) ROM","C) Flash Memory","D) SSD"]},{"numb":16,"type":"Multiple Choices","question":"What is the primary function of cache memory?","answer":"B) To store frequently accessed data and instructions for quicker access","options":["A) To store long-term data","B) To store frequently accessed data and instructions for quicker access","C) To store backup data","D) To store system configuration settings"]},{"numb":17,"type":"Multiple Choices","question":"Which of the following coding systems uses 32 bits per character to represent text-based data?","answer":"D) Unicode","options":["A) ASCII","B) EBCDIC","C) Hexadecimal","D) Unicode"]},{"numb":18,"type":"Multiple Choices","question":"Which storage unit is approximately equal to one million bytes?","answer":"C) Megabyte","options":["A) Kilobyte","B) Gigabyte","C) Megabyte","D) Terabyte"]},{"numb":19,"type":"Multiple Choices","question":"Which unit is used to measure the clock speed of a CPU?","answer":"B) Gigahertz (GHz)","options":["A) Megaflops","B) Gigahertz (GHz)","C) Teraflops","D) Megabytes per second"]},{"numb":20,"type":"Multiple Choices","question":"Which of the following is NOT an example of a binary numbering system?","answer":"D) Decimal","options":["A) 1001","B) 1100","C) 0101","D) Decimal"]},{"numb":21,"type":"Multiple Choices","question":"How many bits are in a byte?","answer":"B) 8","options":["A) 4","B) 8","C) 16","D) 32"]},{"numb":22,"type":"Multiple Choices","question":"Which unit of data measures approximately one trillion bytes?","answer":"C) Terabyte","options":["A) Kilobyte","B) Megabyte","C) Terabyte","D) Gigabyte"]},{"numb":23,"type":"Multiple Choices","question":"Which component of a computer is responsible for processing visual data and rendering graphics?","answer":"D) GPU","options":["A) CPU","B) RAM","C) FPU","D) GPU"]},{"numb":24,"type":"Multiple Choices","question":"What is the name of the main circuit board in a computer?","answer":"B) Motherboard","options":["A) Processor","B) Motherboard","C) RAM","D) Bus"]},{"numb":25,"type":"Multiple Choices","question":"Which of the following is a system for representing text data using 7 or 8 bits per character?","answer":"A) ASCII","options":["A) ASCII","B) Unicode","C) EBCDIC","D) Decimal"]},{"numb":26,"type":"Multiple Choices","question":"What type of image is made up of a grid of small dots called pixels?","answer":"C) Bitmapped image","options":["A) Vector image","B) Scalable image","C) Bitmapped image","D) Monochrome image"]},{"numb":27,"type":"Multiple Choices","question":"What is the function of the system clock in a computer?","answer":"B) Synchronize the computer''s operations","options":["A) Store data","B) Synchronize the computer''s operations","C) Increase the processing speed","D) Convert data into binary"]},{"numb":28,"type":"Multiple Choices","question":"Which of the following describes the CPU''s ability to perform more than one task at a time?","answer":"D) Multi-core processing","options":["A) Hyper-threading","B) Overclocking","C) Virtualization","D) Multi-core processing"]},{"numb":29,"type":"Multiple Choices","question":"What type of bus connects the CPU to RAM?","answer":"A) Memory Bus","options":["A) Memory Bus","B) PCI Bus","C) USB Bus","D) FireWire Bus"]},{"numb":30,"type":"Multiple Choices","question":"What does ROM stand for?","answer":"C) Read-Only Memory","options":["A) Random Output Module","B) Rewritable Optical Media","C) Read-Only Memory","D) Removable Output Memory"]},{"numb":31,"type":"Multiple Choices","question":"Which component handles arithmetic and logical operations within the CPU?","answer":"B) ALU","options":["A) FPU","B) ALU","C) Cache","D) Control Unit"]},{"numb":32,"type":"Multiple Choices","question":"Which term refers to the CPU''s ability to fetch data before it is needed for processing?","answer":"A) Prefetch","options":["A) Prefetch","B) Cache","C) Buffering","D) Paging"]},{"numb":33,"type":"Multiple Choices","question":"Which type of memory is built directly into the CPU?","answer":"C) Registers","options":["A) RAM","B) ROM","C) Registers","D) Flash Memory"]},{"numb":34,"type":"Multiple Choices","question":"Which type of processor contains four cores?","answer":"B) Quad-core CPU","options":["A) Dual-core CPU","B) Quad-core CPU","C) Hexa-core CPU","D) Octa-core CPU"]},{"numb":35,"type":"Multiple Choices","question":"What is a common unit for measuring CPU clock speed?","answer":"A) Gigahertz (GHz)","options":["A) Gigahertz (GHz)","B) Megabytes per second","C) Teraflops","D) Megaflops"]},{"numb":36,"type":"Multiple Choices","question":"Which storage device typically uses flash memory technology?","answer":"B) SSD","options":["A) HDD","B) SSD","C) Blu-ray Disc","D) CD-ROM"]},{"numb":37,"type":"Multiple Choices","question":"Which port is commonly used to connect external multimedia devices to a computer?","answer":"D) FireWire","options":["A) VGA","B) HDMI","C) USB","D) FireWire"]},{"numb":38,"type":"Multiple Choices","question":"Which memory is non-volatile and used for long-term storage?","answer":"B) ROM","options":["A) RAM","B) ROM","C) Registers","D) Cache"]},{"numb":39,"type":"Multiple Choices","question":"Which component of the CPU performs arithmetic involving decimal numbers?","answer":"C) FPU","options":["A) ALU","B) Cache","C) FPU","D) Control Unit"]},{"numb":40,"type":"Multiple Choices","question":"What is the primary purpose of a heat sink in a computer?","answer":"C) To dissipate heat from the CPU","options":["A) To increase airflow","B) To cool the motherboard","C) To dissipate heat from the CPU","D) To store energy"]},{"numb":41,"type":"Multiple Choices","question":"Which type of memory is considered volatile?","answer":"A) RAM","options":["A) RAM","B) ROM","C) Flash Memory","D) SSD"]},{"numb":42,"type":"Multiple Choices","question":"Which expansion bus is used to connect peripheral devices such as printers to a computer?","answer":"B) USB","options":["A) PCIe","B) USB","C) FireWire","D) PCI"]},{"numb":43,"type":"Multiple Choices","question":"Which term describes the amount of data a CPU can process at one time?","answer":"C) Word Size","options":["A) Bus Width","B) Cache Size","C) Word Size","D) Clock Speed"]},{"numb":44,"type":"Multiple Choices","question":"Which of the following is used to represent video data in digital form?","answer":"C) Frames","options":["A) Pixels","B) Bits","C) Frames","D) Samples"]},{"numb":45,"type":"Multiple Choices","question":"What is the role of the Control Unit in the CPU?","answer":"B) To coordinate and control the CPU''s activities","options":["A) To perform arithmetic operations","B) To coordinate and control the CPU''s activities","C) To store data","D) To fetch instructions"]},{"numb":46,"type":"Multiple Choices","question":"Which memory technology is commonly used in smartphones for long-term storage?","answer":"C) Flash Memory","options":["A) RAM","B) ROM","C) Flash Memory","D) Registers"]},{"numb":47,"type":"Multiple Choices","question":"Which of the following is a type of bus that connects the CPU to peripheral devices?","answer":"D) Expansion Bus","options":["A) Memory Bus","B) System Bus","C) Data Bus","D) Expansion Bus"]},{"numb":48,"type":"Multiple Choices","question":"Which coding system is used for universal representation of text data written in any language?","answer":"C) Unicode","options":["A) ASCII","B) EBCDIC","C) Unicode","D) Binary"]},{"numb":49,"type":"Multiple Choices","question":"What does USB stand for?","answer":"B) Universal Serial Bus","options":["A) Uniform Storage Bus","B) Universal Serial Bus","C) Universal Synchronous Bus","D) Unit Storage Bus"]},{"numb":50,"type":"Multiple Choices","question":"Which of the following is the most significant component of a computer''s processing power?","answer":"C) CPU","options":["A) GPU","B) SSD","C) CPU","D) RAM"]}]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_003', 'Chapter 3 : Storage', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"What type of storage media is DVD classified as?","answer":"B) Optical","options":["A) Magnetic","B) Optical","C) Solid-State","D) Cloud"]},{"numb":2,"type":"Multiple Choices","question":"Which device reads from a DVD disc?","answer":"B) DVD drive","options":["A) Flash drive","B) DVD drive","C) SSD","D) Magnetic tape"]},{"numb":3,"type":"Multiple Choices","question":"What is an example of a nonvolatile storage medium?","answer":"C) Flash memory","options":["A) RAM","B) Cache","C) Flash memory","D) Processor"]},{"numb":4,"type":"Multiple Choices","question":"What type of access allows data to be retrieved from any location on the storage medium?","answer":"B) Direct access","options":["A) Sequential access","B) Direct access","C) Serial access","D) Magnetic access"]},{"numb":5,"type":"Multiple Choices","question":"What is an example of a storage device?","answer":"C) Blu-ray disc drive","options":["A) Program","B) Document","C) Blu-ray disc drive","D) Video game"]},{"numb":6,"type":"Multiple Choices","question":"What term refers to the logical division of a hard drive’s capacity?","answer":"B) Partition","options":["A) Cylinder","B) Partition","C) Track","D) Cluster"]},{"numb":7,"type":"Multiple Choices","question":"What type of optical disc is rewritable?","answer":"B) CD-RW","options":["A) DVD-ROM","B) CD-RW","C) BD-ROM","D) CD-ROM"]},{"numb":8,"type":"Multiple Choices","question":"What technology does an SSD use?","answer":"B) Flash memory technology","options":["A) Magnetic technology","B) Flash memory technology","C) Optical technology","D) Holographic technology"]},{"numb":9,"type":"Multiple Choices","question":"What component in a magnetic hard drive reads and writes data?","answer":"C) Read/write head","options":["A) SSD chip","B) Laser beam","C) Read/write head","D) Flash memory"]},{"numb":10,"type":"Multiple Choices","question":"What term describes a concentric path on a disk where data is recorded?","answer":"C) Track","options":["A) Sector","B) Cluster","C) Track","D) Partition"]},{"numb":11,"type":"Multiple Choices","question":"What device is typically used to increase the storage capacity of a tablet?","answer":"D) Wireless hard drive","options":["A) SSD","B) Cloud storage","C) Optical disc drive","D) Wireless hard drive"]},{"numb":12,"type":"Multiple Choices","question":"Each track divided into small parts called called?","answer":"A) Sectors","options":["A) Sectors","B) Clusters","C) Tracks","D) Cylinders"]},{"numb":13,"type":"Multiple Choices","question":"What is a key advantage of SSDs over traditional magnetic hard drives?","answer":"A) More durable","options":["A) More durable","B) Lower cost","C) Larger capacity","D) Greater size"]},{"numb":14,"type":"Multiple Choices","question":"What type of storage is used to access files over the Internet?","answer":"B) Cloud storage","options":["A) Flash storage","B) Cloud storage","C) External hard drive","D) Network attached storage"]},{"numb":15,"type":"Multiple Choices","question":"What term refers to the total time a hard drive takes to read or write data?","answer":"C) Disk access time","options":["A) Rotational delay","B) Seek time","C) Disk access time","D) Data movement time"]},{"numb":16,"type":"Multiple Choices","question":"What kind of media is used by a solid-state drive (SSD)?","answer":"B) Flash memory media","options":["A) Optical media","B) Flash memory media","C) Magnetic media","D) DNA data storage"]},{"numb":17,"type":"Multiple Choices","question":"Which of the following is NOT a type of optical disc?","answer":"C) USB drive","options":["A) CD","B) Blu-ray","C) USB drive","D) DVD"]},{"numb":18,"type":"Multiple Choices","question":"What term refers to a method of storing data on two or more hard drives that work together?","answer":"A) RAID","options":["A) RAID","B) Cloud storage","C) Partitioning","D) Sequential access"]},{"numb":19,"type":"Multiple Choices","question":"What does RAID 1 represent?","answer":"B) Disk mirroring","options":["A) Disk striping","B) Disk mirroring","C) Hybrid hard drive","D) Holographic storage"]},{"numb":20,"type":"Multiple Choices","question":"What is the common standard used by older hard drives to connect to a computer?","answer":"D) Parallel ATA (PATA)","options":["A) SATA","B) SCSI","C) Fibre Channel","D) Parallel ATA (PATA)"]},{"numb":21,"type":"Multiple Choices","question":"What is the key advantage of optical discs over magnetic storage?","answer":"B) Durability","options":["A) Higher speed","B) Durability","C) Higher cost","D) Shorter lifespan"]},{"numb":22,"type":"Multiple Choices","question":"What is a mini-disc?","answer":"B) 80 mm disc","options":["A) 120 mm disc","B) 80 mm disc","C) 50 mm disc","D) 10 mm disc"]},{"numb":23,"type":"Multiple Choices","question":"What technology is used in Blu-ray discs to increase capacity?","answer":"A) Dual-layer recording","options":["A) Dual-layer recording","B) Magnetic recording","C) Cloud technology","D) RAID"]},{"numb":24,"type":"Multiple Choices","question":"What type of access does magnetic tape use?","answer":"C) Sequential access","options":["A) Random access","B) Direct access","C) Sequential access","D) Parallel access"]},{"numb":25,"type":"Multiple Choices","question":"What type of storage system is a NAS?","answer":"A) Network attached storage","options":["A) Network attached storage","B) Solid-state storage","C) Local hard drive","D) Hybrid hard drive"]},{"numb":26,"type":"Multiple Choices","question":"What kind of storage is typically used for archiving large amounts of data quickly?","answer":"B) Magnetic tape","options":["A) Optical disc","B) Magnetic tape","C) SSD","D) Holographic storage"]},{"numb":27,"type":"Multiple Choices","question":"What is the purpose of a disk cache?","answer":"A) Improve system performance","options":["A) Improve system performance","B) Encrypt data","C) Increase storage space","D) Back up data"]},{"numb":28,"type":"Multiple Choices","question":"What is the key advantage of a hybrid hard drive?","answer":"D) Combination of flash memory and magnetic storage","options":["A) Faster access time","B) Higher storage capacity","C) Integrated cloud storage","D) Combination of flash memory and magnetic storage"]},{"numb":29,"type":"Multiple Choices","question":"What standard is used for connecting SSDs in high-performance computers?","answer":"B) SATA","options":["A) PATA","B) SATA","C) iSCSI","D) Fibre Channel"]},{"numb":30,"type":"Multiple Choices","question":"Which of the following is a common use of smart cards?","answer":"A) Storing biometric data","options":["A) Storing biometric data","B) Storing large amounts of data","C) Backing up data","D) Random access storage"]},{"numb":31,"type":"Multiple Choices","question":"What is the storage capacity of a standard CD-ROM disc?","answer":"A) 700 MB","options":["A) 700 MB","B) 4.7 GB","C) 25 GB","D) 50 GB"]},{"numb":32,"type":"Multiple Choices","question":"Which RAID level uses both disk striping and disk mirroring?","answer":"D) RAID 10","options":["A) RAID 0","B) RAID 1","C) RAID 5","D) RAID 10"]},{"numb":33,"type":"Multiple Choices","question":"Which type of optical disc can store the most data?","answer":"C) BD-ROM","options":["A) CD-ROM","B) DVD-ROM","C) BD-ROM","D) DVD-RW"]},{"numb":34,"type":"Multiple Choices","question":"What type of storage is commonly used for gaming consoles and handheld devices?","answer":"B) Flash memory","options":["A) Holographic storage","B) Flash memory","C) Optical discs","D) Magnetic tape"]},{"numb":35,"type":"Multiple Choices","question":"What component of a hard drive physically reads and writes data?","answer":"C) Read/write head","options":["A) Track","B) Sector","C) Read/write head","D) Disk cache"]},{"numb":36,"type":"Multiple Choices","question":"Which of the following is a common use for a smart card?","answer":"C) Secure transactions","options":["A) Storing multimedia files","B) Processing data at high speed","C) Secure transactions","D) Data archiving"]},{"numb":37,"type":"Multiple Choices","question":"What is the main advantage of cloud storage?","answer":"C) Remote access from anywhere with Internet","options":["A) Faster read and write speeds","B) Cheaper than hard drives","C) Remote access from anywhere with Internet","D) Higher storage capacity"]},{"numb":38,"type":"Multiple Choices","question":"What technology is used in magnetic hard drives to store data?","answer":"B) Magnets","options":["A) Lasers","B) Magnets","C) Electrical charge","D) DNA strands"]},{"numb":39,"type":"Multiple Choices","question":"What type of disc is used to store high-definition video?","answer":"C) BD-ROM","options":["A) CD-ROM","B) DVD-ROM","C) BD-ROM","D) SSD"]},{"numb":40,"type":"Multiple Choices","question":"Which component in an SSD stores data?","answer":"B) Flash memory chips","options":["A) Magnetic platters","B) Flash memory chips","C) Optical lasers","D) Disk cache"]},{"numb":41,"type":"Multiple Choices","question":"What is the purpose of using a partition on a hard drive?","answer":"B) To create logical sections of a drive","options":["A) To increase physical storage capacity","B) To create logical sections of a drive","C) To store backup data","D) To read data faster"]},{"numb":42,"type":"Multiple Choices","question":"Which of the following storage devices uses sequential access?","answer":"C) Magnetic tape","options":["A) SSD","B) Hard drive","C) Magnetic tape","D) Blu-ray disc"]},{"numb":43,"type":"Multiple Choices","question":"Which of the following has the largest storage capacity?","answer":"C) Blu-ray Disc","options":["A) CD","B) DVD","C) Blu-ray Disc","D) Flash memory card"]},{"numb":44,"type":"Multiple Choices","question":"Which type of storage device is best suited for portable computers and mobile devices?","answer":"C) SSD","options":["A) Magnetic hard drive","B) Optical disc drive","C) SSD","D) Magnetic tape"]},{"numb":45,"type":"Multiple Choices","question":"What storage device is most likely to be found in a data center for large-scale storage needs?","answer":"B) NAS (Network Attached Storage)","options":["A) External USB drive","B) NAS (Network Attached Storage)","C) SSD","D) Smart card"]},{"numb":46,"type":"Multiple Choices","question":"What is the main purpose of RAID technology?","answer":"B) To store redundant data and improve fault tolerance","options":["A) To reduce cost of storage","B) To store redundant data and improve fault tolerance","C) To reduce the physical size of storage devices","D) To increase the read/write speed of SSDs"]},{"numb":47,"type":"Multiple Choices","question":"Which standard is commonly used to connect high-performance SSDs to servers?","answer":"B) SAS (Serial Attached SCSI)","options":["A) PATA","B) SAS (Serial Attached SCSI)","C) USB","D) Smart Card"]},{"numb":48,"type":"Multiple Choices","question":"What is a characteristic of a holographic storage system?","answer":"B) It stores data in three dimensions using laser beams","options":["A) It uses a magnetic field to store data","B) It stores data in three dimensions using laser beams","C) It stores data using electrical charge","D) It uses optical discs as the main medium"]},{"numb":49,"type":"Multiple Choices","question":"What is a USB flash drive often called?","answer":"A) Jump drive","options":["A) Jump drive","B) SSD","C) Cloud drive","D) NAS drive"]},{"numb":50,"type":"Multiple Choices","question":"What type of optical disc drive is capable of burning data onto a disc?","answer":"C) BD-RW drive","options":["A) CD-ROM drive","B) DVD-ROM drive","C) BD-RW drive","D) Blu-ray player"]}]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_004', 'Chapter 4 : Input and Output', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"What is the primary function of a keyboard?","answer":"B) To enter characters into a computer","options":["A) To display images","B) To enter characters into a computer","C) To print documents","D) To store data"]},{"numb":2,"type":"Multiple Choices","question":"Which of the following is a type of keyboard used in mobile devices?","answer":"C) On-screen keyboard","options":["A) Mechanical keyboard","B) Ergonomic keyboard","C) On-screen keyboard","D) Membrane keyboard"]},{"numb":3,"type":"Multiple Choices","question":"What is the main purpose of a mouse?","answer":"B) To point and select objects on the screen","options":["A) To type text","B) To point and select objects on the screen","C) To scan documents","D) To print images"]},{"numb":4,"type":"Multiple Choices","question":"Which type of mouse tracks movements using light?","answer":"B) Optical mouse","options":["A) Mechanical mouse","B) Optical mouse","C) Ball mouse","D) Trackball mouse"]},{"numb":5,"type":"Multiple Choices","question":"What is a stylus used for?","answer":"A) Drawing or writing on a screen","options":["A) Drawing or writing on a screen","B) Printing documents","C) Capturing audio input","D) Storing digital data"]},{"numb":6,"type":"Multiple Choices","question":"Which device is used to convert printed text and images into digital form?","answer":"B) Scanner","options":["A) Printer","B) Scanner","C) Monitor","D) Keyboard"]},{"numb":7,"type":"Multiple Choices","question":"What is the function of an Optical Mark Reader (OMR)?","answer":"C) To tally exams and questionnaires","options":["A) To read barcodes","B) To scan images","C) To tally exams and questionnaires","D) To capture biometric data"]},{"numb":8,"type":"Multiple Choices","question":"Which of the following technologies is used by RFID readers?","answer":"B) Radio frequency identification","options":["A) Barcode scanning","B) Radio frequency identification","C) Optical character recognition","D) Magnetic ink character recognition"]},{"numb":9,"type":"Multiple Choices","question":"What is a primary feature of a digital camera?","answer":"B) Takes pictures and records them as digital images","options":["A) Prints photos directly","B) Takes pictures and records them as digital images","C) Scans documents into digital form","D) Outputs audio data"]},{"numb":10,"type":"Multiple Choices","question":"What is the quality of a digital camera measured in?","answer":"B) Megapixels","options":["A) Gigabytes","B) Megapixels","C) Kilobytes","D) Lumens"]},{"numb":11,"type":"Multiple Choices","question":"Which of the following is a characteristic of a display device?","answer":"B) Displays visual output on a screen","options":["A) Outputs audio","B) Displays visual output on a screen","C) Scans documents","D) Captures digital images"]},{"numb":12,"type":"Multiple Choices","question":"What is the primary difference between CRT and flat-panel displays?","answer":"C) Flat-panel displays use less power and take up less space","options":["A) Flat-panel displays are bulkier","B) CRT displays are smaller","C) Flat-panel displays use less power and take up less space","D) CRT displays use LED technology"]},{"numb":13,"type":"Multiple Choices","question":"Which of the following types of display is most commonly used in modern devices?","answer":"C) Flat-panel displays","options":["A) Monochrome displays","B) CRT displays","C) Flat-panel displays","D) Plasma displays"]},{"numb":14,"question":"What type of printer uses toner powder?","answer":"C) Laser printer","options":["A) Inkjet printer","B) Dot matrix printer","C) Laser printer","D) Thermal printer"]},{"numb":15,"type":"Multiple Choices","question":"Which printing technology is used to produce multipart forms?","answer":"B) Impact printing","options":["A) Inkjet printing","B) Impact printing","C) Non-impact printing","D) 3D printing"]},{"numb":16,"type":"Multiple Choices","question":"What does dpi stand for in printing?","answer":"A) Dots per inch","options":["A) Dots per inch","B) Data per input","C) Depth per inch","D) Digital printing index"]},{"numb":17,"type":"Multiple Choices","question":"Which device is used to input voice data into a computer?","answer":"B) Microphone","options":["A) Monitor","B) Microphone","C) Printer","D) Keyboard"]},{"numb":18,"type":"Multiple Choices","question":"What is the primary use of a speech recognition system?","answer":"B) To recognize and convert spoken words into digital text","options":["A) To output sound","B) To recognize and convert spoken words into digital text","C) To print text","D) To display images on the screen"]},{"numb":19,"type":"Multiple Choices","question":"Which of the following is an audio output device?","answer":"B) Speaker","options":["A) Monitor","B) Speaker","C) Scanner","D) Keyboard"]},{"numb":20,"type":"Multiple Choices","question":"What is a touch screen?","answer":"B) A display device that allows input by touching the screen","options":["A) A device used to scan images","B) A display device that allows input by touching the screen","C) A device that captures audio input","D) A printer that uses touch input"]},{"numb":21,"type":"Multiple Choices","question":"Which device is typically used in gaming and allows for full-body input?","answer":"C) Perceptual computing system","options":["A) Trackball","B) Joystick","C) Perceptual computing system","D) Barcode reader"]},{"numb":22,"type":"Multiple Choices","question":"What is an example of a biometric reader?","answer":"B) A device that captures fingerprint or voice data","options":["A) A scanner that reads printed text","B) A device that captures fingerprint or voice data","C) A pen-like device used to input drawings","D) A mouse that tracks movement with light"]},{"numb":23,"type":"Multiple Choices","question":"What technology do e-readers primarily use?","answer":"C) E-paper","options":["A) OLED","B) LCD","C) E-paper","D) Plasma"]},{"numb":24,"type":"Multiple Choices","question":"Which of the following is considered an input device?","answer":"C) Keyboard","options":["A) Monitor","B) Printer","C) Keyboard","D) Speaker"]},{"numb":25,"type":"Multiple Choices","question":"What does OCR stand for?","answer":"C) Optical Character Recognition","options":["A) Optical Code Reader","B) Output Control Reader","C) Optical Character Recognition","D) Output Character Resolution"]},{"numb":26,"type":"Multiple Choices","question":"Which of these is a non-impact printer?","answer":"B) Laser printer","options":["A) Dot matrix printer","B) Laser printer","C) Typewriter","D) All of the above"]},{"numb":27,"type":"Multiple Choices","question":"What type of scanner would be most appropriate for capturing detailed 3D models?","answer":"C) 3D scanner","options":["A) Flatbed scanner","B) Portable scanner","C) 3D scanner","D) Barcode scanner"]},{"numb":28,"type":"Multiple Choices","question":"Which of these is NOT a characteristic of OLED displays?","answer":"B) Require backlighting","options":["A) Use layers of organic material","B) Require backlighting","C) Have deep black levels","D) Are used in smartphones"]},{"numb":29,"type":"Multiple Choices","question":"Which technology is most suitable for immersive virtual reality experiences?","answer":"B) VR headset","options":["A) Trackball","B) VR headset","C) Dot matrix printer","D) Barcode scanner"]},{"numb":30,"type":"Multiple Choices","question":"What type of output is produced by a projector?","answer":"C) Visual display","options":["A) Audio output","B) Printed output","C) Visual display","D) Tactile feedback"]},{"numb":31,"type":"Multiple Choices","question":"Which technology is used to display images on a screen by controlling light through liquid crystals?","answer":"B) LCD","options":["A) CRT","B) LCD","C) Plasma","D) LED"]},{"numb":32,"type":"Multiple Choices","question":"Which device would best allow a user to interact with a computer without touching the screen?","answer":"B) Motion sensor","options":["A) Trackpad","B) Motion sensor","C) Keyboard","D) Joystick"]},{"numb":33,"type":"Multiple Choices","question":"Which of these is an example of an audio input device?","answer":"A) Microphone","options":["A) Microphone","B) Speaker","C) Monitor","D) Keyboard"]},{"numb":34,"type":"Multiple Choices","question":"Which technology is used in barcode scanners?","answer":"B) Laser scanning","options":["A) RFID","B) Laser scanning","C) OCR","D) Digital imaging"]},{"numb":35,"type":"Multiple Choices","question":"Which of the following is a characteristic of plasma displays?","answer":"A) Use small cells containing electrically charged ionized gases","options":["A) Use small cells containing electrically charged ionized gases","B) Require backlighting","C) Are primarily used in e-readers","D) Are typically smaller than 20 inches"]},{"numb":36,"type":"Multiple Choices","question":"What is the main feature of a graphics tablet?","answer":"A) Allows users to draw directly on the surface with a stylus","options":["A) Allows users to draw directly on the surface with a stylus","B) Scans 3D objects","C) Captures biometric data","D) Prints 3D models"]},{"numb":37,"type":"Multiple Choices","question":"Which device is often used in retail for quick checkout?","answer":"B) Barcode scanner","options":["A) OCR reader","B) Barcode scanner","C) Document scanner","D) Webcam"]},{"numb":38,"type":"Multiple Choices","question":"What is the primary function of a webcam?","answer":"A) Capturing video for online communication","options":["A) Capturing video for online communication","B) Scanning documents","C) Printing images","D) Projecting visual displays"]},{"numb":39,"type":"Multiple Choices","question":"Which of these devices is most suitable for video conferencing?","answer":"A) Webcam","options":["A) Webcam","B) Printer","C) Graphics tablet","D) Speaker"]},{"numb":40,"type":"Multiple Choices","question":"What type of device is a touchpad?","answer":"A) Input device","options":["A) Input device","B) Output device","C) Storage device","D) Network device"]},{"numb":41,"type":"Multiple Choices","question":"What is the main advantage of using a trackball over a traditional mouse?","answer":"B) It requires less desk space and is stationary","options":["A) It is more portable","B) It requires less desk space and is stationary","C) It provides better precision","D) It is wireless"]},{"numb":42,"type":"Multiple Choices","question":"Which device is best suited for interactive presentations?","answer":"B) Smartboard","options":["A) Projector","B) Smartboard","C) Laser printer","D) Dot matrix printer"]},{"numb":43,"type":"Multiple Choices","question":"What does a 3D mouse typically allow?","answer":"B) Manipulation of objects in a 3D environment","options":["A) Regular pointing and clicking","B) Manipulation of objects in a 3D environment","C) Only horizontal and vertical movement","D) Audio input"]},{"numb":44,"type":"Multiple Choices","question":"Which device is designed for capturing video footage in various lighting conditions?","answer":"C) Camcorder","options":["A) Digital camera","B) Web camera","C) Camcorder","D) Document camera"]},{"numb":45,"type":"Multiple Choices","question":"What is the primary use of a VR headset?","answer":"B) To experience 3D virtual environments","options":["A) To project 2D images","B) To experience 3D virtual environments","C) To capture real-world images","D) To scan documents"]},{"numb":46,"type":"Multiple Choices","question":"Which device can be used to blend real-world and digital environments?","answer":"B) Mixed reality headset","options":["A) VR headset","B) Mixed reality headset","C) Laser projector","D) Digital scanner"]},{"numb":47,"type":"Multiple Choices","question":"Which input device is crucial for interacting with a virtual reality environment?","answer":"B) VR controller","options":["A) Mouse","B) VR controller","C) Keyboard","D) Trackpad"]},{"numb":48,"type":"Multiple Choices","question":"What kind of displays are typically used in smart glasses?","answer":"B) OLED","options":["A) CRT","B) OLED","C) LCD","D) E-ink"]},{"numb":49,"type":"Multiple Choices","question":"Which technology is used for remote surgeries to control surgical tools from a distance?","answer":"C) Telepresence robotics","options":["A) Digital writing system","B) Augmented reality","C) Telepresence robotics","D) Barcode scanner"]},{"numb":50,"type":"Multiple Choices","question":"What does LIDAR technology primarily measure?","answer":"B) Light reflection to measure distances","options":["A) Audio frequency","B) Light reflection to measure distances","C) Temperature variations","D) Magnetic fields"]}]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_005', 'Chapter 5 : System Software', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"What is the purpose of a file extension?","answer":"B) To identify the type of file","options":["A) To compress the file","B) To identify the type of file","C) To encrypt the file","D) To format the file"]},{"numb":2,"type":"Multiple Choices","question":"Which of the following is an example of application software?","answer":"C) Word Processor","options":["A) Operating System","B) Utility Program","C) Word Processor","D) Device Driver"]},{"numb":3,"type":"Multiple Choices","question":"What is the role of an operating system?","answer":"B) To manage and coordinate activities within a computer","options":["A) To create new hardware","B) To manage and coordinate activities within a computer","C) To protect the computer from viruses","D) To design software applications"]},{"numb":4,"type":"Multiple Choices","question":"Which of the following is not a function of an operating system?","answer":"C) Designing websites","options":["A) Interfacing with users","B) Booting the computer","C) Designing websites","D) Managing network connections"]},{"numb":5,"type":"Multiple Choices","question":"Which of the following is a method to enhance processing efficiency in operating systems?","answer":"D) All of the above","options":["A) Buffering","B) Virtual memory","C) Multitasking","D) All of the above"]},{"numb":6,"type":"Multiple Choices","question":"What does GUI stand for?","answer":"A) Graphical User Interface","options":["A) Graphical User Interface","B) General User Interface","C) Graphic Utility Integration","D) General Utility Interface"]},{"numb":7,"type":"Multiple Choices","question":"What is the purpose of device drivers?","answer":"B) To manage the interaction between hardware and the operating system","options":["A) To create new devices","B) To manage the interaction between hardware and the operating system","C) To design user interfaces","D) To encrypt files"]},{"numb":8,"type":"Multiple Choices","question":"What is multitasking?","answer":"B) Running multiple programs simultaneously","options":["A) Running multiple operating systems simultaneously","B) Running multiple programs simultaneously","C) Running multiple threads in a single program","D) None of the above"]},{"numb":9,"type":"Multiple Choices","question":"What is virtual memory?","answer":"C) Hard drive space used as additional RAM","options":["A) The physical memory installed in a computer","B) A type of RAM","C) Hard drive space used as additional RAM","D) The main storage of the computer"]},{"numb":10,"type":"Multiple Choices","question":"What does spooling stand for?","answer":"B) Simultaneous Peripheral Operations On-Line","options":["A) Sequential Programming","B) Simultaneous Peripheral Operations On-Line","C) Special Program Operating Logic","D) Sequential Peripheral Operations On-Line"]},{"numb":11,"type":"Multiple Choices","question":"Which of the following uses a command-line interface?","answer":"B) DOS","options":["A) Windows","B) DOS","C) Mac OS","D) Linux"]},{"numb":12,"type":"Multiple Choices","question":"Which operating system is known for its use in servers and workstations?","answer":"C) UNIX","options":["A) Windows XP","B) Mac OS","C) UNIX","D) Chrome OS"]},{"numb":13,"type":"Multiple Choices","question":"What does PnP stand for in computing?","answer":"A) Plug and Play","options":["A) Plug and Play","B) Play and Pause","C) Plug and Pause","D) Print and Play"]},{"numb":14,"type":"Multiple Choices","question":"Which operating system is open source and was developed by L.Torvalds?","answer":"D) Linux","options":["A) Windows","B) Mac OS","C) UNIX","D) Linux"]},{"numb":15,"type":"Multiple Choices","question":"Which version of Windows introduced the Aero interface?","answer":"C) Windows Vista","options":["A) Windows XP","B) Windows 7","C) Windows Vista","D) Windows 8"]},{"numb":16,"type":"Multiple Choices","question":"What is the primary function of a firewall?","answer":"B) To protect against unauthorized access","options":["A) To store data","B) To protect against unauthorized access","C) To manage network connections","D) To optimize storage space"]},{"numb":17,"type":"Multiple Choices","question":"What does the term ''buffering'' refer to in operating systems?","answer":"B) Storing data temporarily","options":["A) Increasing processing speed","B) Storing data temporarily","C) Encrypting data","D) Compressing files"]},{"numb":18,"type":"Multiple Choices","question":"Which operating system is primarily designed for smartphones?","answer":"C) Android","options":["A) Windows XP","B) Mac OS","C) Android","D) Linux"]},{"numb":19,"type":"Multiple Choices","question":"What is the role of a file management program?","answer":"C) To organize and manage files and folders","options":["A) To create new files","B) To manage the system''s hardware","C) To organize and manage files and folders","D) To secure the computer"]},{"numb":20,"type":"Multiple Choices","question":"Which of the following is a common feature in most operating systems today?","answer":"B) Graphical user interface","options":["A) Command line interface","B) Graphical user interface","C) Manual memory management","D) No multitasking"]},{"numb":21,"type":"Multiple Choices","question":"Which of the following operating systems is known for being proprietary to Apple?","answer":"B) Mac OS","options":["A) Windows","B) Mac OS","C) Linux","D) UNIX"]},{"numb":22,"type":"Multiple Choices","question":"What is a thread in the context of computing?","answer":"B) A sequence of instructions within a program","options":["A) A type of computer virus","B) A sequence of instructions within a program","C) A method of file compression","D) A type of user interface"]},{"numb":23,"type":"Multiple Choices","question":"What is the primary purpose of utility programs?","answer":"B) To perform specific tasks related to managing or maintaining the computer system","options":["A) To create new software applications","B) To perform specific tasks related to managing or maintaining the computer system","C) To design user interfaces","D) To manage network connections"]},{"numb":24,"type":"Multiple Choices","question":"Which operating system was dominant in the 1980s and early 1990s?","answer":"C) DOS","options":["A) Windows","B) Mac OS","C) DOS","D) UNIX"]},{"numb":25,"type":"Multiple Choices","question":"What is the purpose of file compression programs?","answer":"B) To reduce file size for storage and transmission","options":["A) To increase file size","B) To reduce file size for storage and transmission","C) To encrypt files","D) To format files for printing"]},{"numb":26,"type":"Multiple Choices","question":"What does the term ''multithreading'' refer to?","answer":"B) Executing multiple threads within a single program simultaneously","options":["A) Executing multiple programs simultaneously","B) Executing multiple threads within a single program simultaneously","C) Executing a single thread in a program","D) Managing multiple files simultaneously"]},{"numb":27,"type":"Multiple Choices","question":"Which operating system was developed by Microsoft Corporation?","answer":"C) Windows","options":["A) Mac OS","B) UNIX","C) Windows","D) Linux"]},{"numb":28,"type":"Multiple Choices","question":"Which version of Windows was designed for both PCs and tablets?","answer":"B) Windows 8","options":["A) Windows XP","B) Windows 8","C) Windows 7","D) Windows 10"]},{"numb":29,"type":"Multiple Choices","question":"Which of the following is not a type of operating system?","answer":"C) Database management system","options":["A) Real-time operating system","B) Multi-user operating system","C) Database management system","D) Distributed operating system"]},{"numb":30,"type":"Multiple Choices","question":"What is the primary purpose of a system restore point?","answer":"B) To return the system to a previous state","options":["A) To increase processing speed","B) To return the system to a previous state","C) To backup all data on the system","D) To delete unnecessary files"]},{"numb":31,"type":"Multiple Choices","question":"What is the role of a scheduler in an operating system?","answer":"C) To manage the execution of processes","options":["A) To manage user files","B) To design software applications","C) To manage the execution of processes","D) To protect the system from malware"]},{"numb":32,"type":"Multiple Choices","question":"Which operating system is open source and based on UNIX?","answer":"C) Linux","options":["A) Windows","B) Mac OS","C) Linux","D) Android"]},{"numb":33,"type":"Multiple Choices","question":"What is the purpose of disk cleanup?","answer":"B) To remove unnecessary files and free up space","options":["A) To format the disk","B) To remove unnecessary files and free up space","C) To install a new operating system","D) To encrypt the files on the disk"]},{"numb":34,"type":"Multiple Choices","question":"What is the role of a hypervisor in virtualization?","answer":"C) To manage virtual machines","options":["A) To create virtual networks","B) To run applications on virtual machines","C) To manage virtual machines","D) To design software applications"]},{"numb":35,"type":"Multiple Choices","question":"Which of the following is not a task of the operating system?","answer":"D) Compiling code","options":["A) Memory management","B) Process management","C) File system management","D) Compiling code"]},{"numb":36,"type":"Multiple Choices","question":"What is the purpose of a swap file?","answer":"B) To extend the physical memory onto the hard drive","options":["A) To store backup data","B) To extend the physical memory onto the hard drive","C) To increase processing speed","D) To manage user files"]},{"numb":37,"type":"Multiple Choices","question":"What is the role of a bootloader in a computer system?","answer":"C) To load the operating system into memory","options":["A) To create backups","B) To encrypt the hard drive","C) To load the operating system into memory","D) To manage user accounts"]},{"numb":38,"type":"Multiple Choices","question":"Which of the following is a characteristic of a real-time operating system (RTOS)?","answer":"B) Fast processing of time-critical tasks","options":["A) High-level user interface","B) Fast processing of time-critical tasks","C) Built-in graphical design tools","D) Large file management capacity"]},{"numb":39,"type":"Multiple Choices","question":"What is the primary purpose of a task manager?","answer":"B) To monitor and manage running processes","options":["A) To design user interfaces","B) To monitor and manage running processes","C) To secure the computer from viruses","D) To manage user accounts"]},{"numb":40,"type":"Multiple Choices","question":"Which of the following is a type of system software?","answer":"A) Device driver","options":["A) Device driver","B) Word processor","C) Spreadsheet program","D) Web browser"]},{"numb":41,"type":"Multiple Choices","question":"What is the purpose of defragmentation?","answer":"B) To optimize the layout of files on a disk","options":["A) To encrypt files","B) To optimize the layout of files on a disk","C) To increase network speed","D) To format a hard drive"]},{"numb":42,"type":"Multiple Choices","question":"Which of the following is a real-time operating system?","answer":"D) RTOS","options":["A) DOS","B) Linux","C) Windows 10","D) RTOS"]},{"numb":43,"type":"Multiple Choices","question":"What does the term ''booting'' refer to?","answer":"B) Starting up a computer","options":["A) Creating a backup","B) Starting up a computer","C) Installing software","D) Shutting down a computer"]},{"numb":44,"type":"Multiple Choices","question":"What is the function of the kernel in an operating system?","answer":"A) Manage hardware resources","options":["A) Manage hardware resources","B) Provide a user interface","C) Encrypt files","D) Manage web browsers"]},{"numb":45,"type":"Multiple Choices","question":"What is the primary use of a command-line interface?","answer":"C) Executing text-based commands","options":["A) Web browsing","B) File management","C) Executing text-based commands","D) Graphical design"]},{"numb":46,"type":"Multiple Choices","question":"What is the purpose of an antivirus program?","answer":"B) To detect and remove malicious software","options":["A) To increase processing speed","B) To detect and remove malicious software","C) To optimize storage space","D) To create a duplicate copy of files"]},{"numb":47,"type":"Multiple Choices","question":"What is the role of the BIOS in a computer system?","answer":"B) Initialize and test hardware during the boot process","options":["A) Manage user accounts","B) Initialize and test hardware during the boot process","C) Design user interfaces","D) Encrypt data"]},{"numb":48,"type":"Multiple Choices","question":"Which of the following is not a type of system software?","answer":"D) Spreadsheet program","options":["A) Operating system","B) Utility software","C) Firmware","D) Spreadsheet program"]},{"numb":49,"type":"Multiple Choices","question":"What is the role of a task manager in an operating system?","answer":"B) To display and manage running applications and processes","options":["A) To manage user files","B) To display and manage running applications and processes","C) To design software applications","D) To secure the computer from viruses"]},{"numb":50,"type":"Multiple Choices","question":"Which operating system was designed for use in IBM-compatible PCs?","answer":"C) Windows","options":["A) Mac OS","B) UNIX","C) Windows","D) Linux"]}]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_006', 'Chapter 6 : Applications Software (1/2)', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"Which of the following is true about open source software?","answer":"D) Open source software can be more stable and secure.","options":["A) Open source software is only available for Linux systems.","B) Open source software is always expensive.","C) Open source software cannot be modified by users.","D) Open source software can be more stable and secure."]},{"numb":2,"type":"Multiple Choices","question":"What is the most widely used open-source operating system?","answer":"A) Linux","options":["A) Linux","B) Windows","C) macOS","D) Android"]},{"numb":3,"type":"Multiple Choices","question":"What is a single-user license typically associated with?","answer":"C) Commercial software","options":["A) Open source software","B) Public domain software","C) Commercial software","D) Freeware"]},{"numb":4,"type":"Multiple Choices","question":"Shareware refers to:","answer":"B) Copyrighted software distributed on the honor system","options":["A) Software that is not copyrighted","B) Copyrighted software distributed on the honor system","C) Software given away for free by the author","D) Software that is part of the public domain"]},{"numb":5,"type":"Multiple Choices","question":"What is true about mobile software?","answer":"D) It is typically downloaded from app stores like Google Play or Apple App Store.","options":["A) It is used only on desktop computers.","B) It does not require a specific device type.","C) It is pre-installed on all devices.","D) It is typically downloaded from app stores like Google Play or Apple App Store."]},{"numb":6,"type":"Multiple Choices","question":"What is a potential disadvantage of cloud software?","answer":"A) Online applications tend to run more slowly.","options":["A) Online applications tend to run more slowly.","B) It requires a physical installation on your computer.","C) It cannot be accessed from any other device.","D) It is always cheaper than installed software."]},{"numb":7,"type":"Multiple Choices","question":"What is typically included in a software suite?","answer":"B) Word processing, spreadsheet, and presentation software.","options":["A) Operating system, antivirus, and firewall software.","B) Word processing, spreadsheet, and presentation software.","C) Browser, cloud storage, and media players.","D) Gaming, graphic design, and music software."]},{"numb":8,"type":"Multiple Choices","question":"What is word processing software primarily used for?","answer":"C) Creating, editing, saving, and printing written documents.","options":["A) Calculating and analyzing numerical data.","B) Creating graphic designs and illustrations.","C) Creating, editing, saving, and printing written documents.","D) Playing and editing audio files."]},{"numb":9,"type":"Multiple Choices","question":"Which of the following is a popular word processing software?","answer":"A) Microsoft Word","options":["A) Microsoft Word","B) Microsoft Excel","C) Microsoft Access","D) Adobe Photoshop"]},{"numb":10,"type":"Multiple Choices","question":"In a spreadsheet, what is a cell?","answer":"C) The intersection of a row and a column.","options":["A) A group of formulas in a spreadsheet.","B) The entire spreadsheet document.","C) The intersection of a row and a column.","D) The title of the spreadsheet."]},{"numb":11,"type":"Multiple Choices","question":"What symbol is typically used to begin a formula in a spreadsheet?","answer":"B) =","options":["A) +","B) =","C) $","D) &"]},{"numb":12,"type":"Multiple Choices","question":"What is a relative cell reference in a spreadsheet?","answer":"A) A reference that changes as the formula is copied to other cells.","options":["A) A reference that changes as the formula is copied to other cells.","B) A reference that stays fixed even when the formula is copied.","C) A reference to the first cell in the worksheet.","D) A reference that sums up the entire row."]},{"numb":13,"type":"Multiple Choices","question":"What is ''what-if analysis'' in a spreadsheet?","answer":"D) A tool used to help make business decisions by changing variables.","options":["A) A method to calculate sums.","B) A way to merge cells.","C) A tool for formatting text in a worksheet.","D) A tool used to help make business decisions by changing variables."]},{"numb":14,"type":"Multiple Choices","question":"Which of the following is a common database management system (DBMS)?","answer":"A) Microsoft Access","options":["A) Microsoft Access","B) Adobe Photoshop","C) Microsoft Excel","D) Google Docs"]},{"numb":15,"type":"Multiple Choices","question":"What is a table in a database?","answer":"C) A collection of related records organized into rows and columns.","options":["A) A visual chart used in presentations.","B) A list of files in a folder.","C) A collection of related records organized into rows and columns.","D) A section of a spreadsheet."]},{"numb":16,"type":"Multiple Choices","question":"What does DBMS stand for?","answer":"B) Database Management System","options":["A) Data Backup and Management System","B) Database Management System","C) Data Banking and Monitoring System","D) Dynamic Buffering Management System"]},{"numb":17,"type":"Multiple Choices","question":"In databases, what is a query?","answer":"A) A request for specific information from the database.","options":["A) A request for specific information from the database.","B) A method of sorting data alphabetically.","C) A tool for editing text in a table.","D) A feature that automatically creates graphs."]},{"numb":18,"type":"Multiple Choices","question":"What is a slide in presentation software?","answer":"C) A one-page presentation graphic that can be displayed in a group with others.","options":["A) A text field in a database.","B) A type of graphic design software.","C) A one-page presentation graphic that can be displayed in a group with others.","D) A type of spreadsheet."]},{"numb":19,"type":"Multiple Choices","question":"What is the most common presentation graphics software?","answer":"A) Microsoft PowerPoint","options":["A) Microsoft PowerPoint","B) Microsoft Excel","C) CorelDRAW","D) Apple Numbers"]},{"numb":20,"type":"Multiple Choices","question":"What is slide sorter view used for in presentation software?","answer":"D) To rearrange the order of slides in the presentation.","options":["A) To add animations to slides.","B) To edit text on a slide.","C) To create new slides.","D) To rearrange the order of slides in the presentation."]},{"numb":21,"type":"Multiple Choices","question":"Which of the following is true about image editing programs?","answer":"B) They are used to modify and enhance digital images.","options":["A) They are used to create 3D models.","B) They are used to modify and enhance digital images.","C) They are used for database management.","D) They are used to play audio files."]},{"numb":22,"type":"Multiple Choices","question":"Which of the following programs is widely used for photo editing?","answer":"A) Adobe Photoshop","options":["A) Adobe Photoshop","B) Microsoft Word","C) Microsoft Excel","D) Google Chrome"]},{"numb":23,"type":"Multiple Choices","question":"What is the primary function of audio capture and editing software?","answer":"B) To create and edit audio files.","options":["A) To create video content.","B) To create and edit audio files.","C) To manage financial data.","D) To create 3D animations."]},{"numb":24,"type":"Multiple Choices","question":"Which of the following is a common video editing software?","answer":"D) Apple iMovie","options":["A) Microsoft Excel","B) Adobe Illustrator","C) Corel Painter","D) Apple iMovie"]},{"numb":25,"type":"Multiple Choices","question":"What are media players primarily used for?","answer":"C) To play audio and video files.","options":["A) To create presentation slides.","B) To edit photos and images.","C) To play audio and video files.","D) To create database reports."]},{"numb":26,"type":"Multiple Choices","question":"Which of the following is a popular media player?","answer":"B) Apple QuickTime","options":["A) Microsoft Word","B) Apple QuickTime","C) Microsoft Excel","D) Adobe Photoshop"]},{"numb":27,"type":"Multiple Choices","question":"What is the purpose of web design software?","answer":"A) To create and modify websites and web content.","options":["A) To create and modify websites and web content.","B) To create databases for companies.","C) To play video games online.","D) To create financial reports."]},{"numb":28,"type":"Multiple Choices","question":"Which of the following software types is used for project management?","answer":"B) Microsoft Project","options":["A) Microsoft Word","B) Microsoft Project","C) Adobe Illustrator","D) Corel Painter"]},{"numb":29,"type":"Multiple Choices","question":"Which software is widely used for personal financial management?","answer":"B) Quicken","options":["A) Microsoft Word","B) Quicken","C) Adobe Illustrator","D) Microsoft Excel"]},{"numb":30,"type":"Multiple Choices","question":"Which of the following is a feature of desktop publishing software?","answer":"C) Creating complex page layouts for printed materials.","options":["A) Managing large datasets.","B) Editing video and audio files.","C) Creating complex page layouts for printed materials.","D) Writing programming code."]},{"numb":31,"type":"Multiple Choices","question":"A key feature of Computer-Aided Design (CAD) software is:","answer":"A) The ability to create detailed 2D and 3D models.","options":["A) The ability to create detailed 2D and 3D models.","B) Editing digital photos.","C) Managing large databases.","D) Creating spreadsheets."]},{"numb":32,"type":"Multiple Choices","question":"Which of the following is a common use for Computer-Aided Design (CAD) software?","answer":"B) Designing buildings, machinery, and electronics.","options":["A) Creating digital artwork for social media.","B) Designing buildings, machinery, and electronics.","C) Editing audio and video files.","D) Managing personal finances."]},{"numb":33,"type":"Multiple Choices","question":"Which software would you use to create 3D animations and visual effects?","answer":"A) Autodesk Maya","options":["A) Autodesk Maya","B) Adobe Photoshop","C) Microsoft Word","D) CorelDRAW"]},{"numb":34,"type":"Multiple Choices","question":"Which of the following software is used to develop web applications?","answer":"B) Adobe Dreamweaver","options":["A) Microsoft Excel","B) Adobe Dreamweaver","C) Microsoft Access","D) Microsoft Paint"]},{"numb":35,"type":"Multiple Choices","question":"What is the main purpose of web development software?","answer":"C) To create and maintain websites and web applications.","options":["A) To manage large databases.","B) To edit photos and images.","C) To create and maintain websites and web applications.","D) To play multimedia content."]},{"numb":36,"type":"Multiple Choices","question":"Which of the following best describes accounting software?","answer":"B) Software designed to manage financial transactions and accounts.","options":["A) Software designed to create artistic designs and illustrations.","B) Software designed to manage financial transactions and accounts.","C) Software used to edit audio and video files.","D) Software used to create presentation slides."]},{"numb":37,"type":"Multiple Choices","question":"Which software is most commonly used for accounting and financial tasks?","answer":"A) QuickBooks","options":["A) QuickBooks","B) Adobe Photoshop","C) Microsoft Excel","D) Microsoft PowerPoint"]},{"numb":38,"type":"Multiple Choices","question":"Which of the following is an example of a project management software?","answer":"C) Asana","options":["A) Adobe Illustrator","B) Microsoft Word","C) Asana","D) Google Chrome"]},{"numb":39,"type":"Multiple Choices","question":"What is the main function of project management software?","answer":"A) To plan, organize, and manage resources and tasks in a project.","options":["A) To plan, organize, and manage resources and tasks in a project.","B) To edit and design digital photos.","C) To write and edit documents.","D) To create 3D models and simulations."]},{"numb":40,"type":"Multiple Choices","question":"Which software is widely used for creating graphic designs and illustrations?","answer":"D) Adobe Illustrator","options":["A) Microsoft Excel","B) Microsoft Word","C) Google Slides","D) Adobe Illustrator"]},{"numb":41,"type":"Multiple Choices","question":"Which of the following is an example of note-taking software?","answer":"C) Microsoft OneNote","options":["A) Microsoft Word","B) Adobe Photoshop","C) Microsoft OneNote","D) Microsoft Excel"]},{"numb":42,"type":"Multiple Choices","question":"What is the primary function of desktop publishing software?","answer":"B) To create professional-quality printed documents like brochures and newsletters.","options":["A) To edit and manage financial data.","B) To create professional-quality printed documents like brochures and newsletters.","C) To manage web development projects.","D) To edit video and audio files."]},{"numb":43,"type":"Multiple Choices","question":"Which software is best suited for managing personal finances?","answer":"A) Quicken","options":["A) Quicken","B) CorelDRAW","C) Adobe Illustrator","D) Microsoft Word"]},{"numb":44,"type":"Multiple Choices","question":"Which software would be used to create an architectural blueprint?","answer":"D) AutoCAD","options":["A) Microsoft Word","B) Google Sheets","C) Microsoft Access","D) AutoCAD"]},{"numb":45,"type":"Multiple Choices","question":"Which of the following best describes collaboration software?","answer":"C) Software that allows multiple people to work together on a single project in real-time.","options":["A) Software for creating documents and spreadsheets.","B) Software that allows you to create digital illustrations.","C) Software that allows multiple people to work together on a single project in real-time.","D) Software used to edit and organize videos."]},{"numb":46,"type":"Multiple Choices","question":"Which of these is an example of cloud-based collaboration software?","answer":"B) Google Docs","options":["A) Microsoft Paint","B) Google Docs","C) Adobe Photoshop","D) CorelDRAW"]},{"numb":47,"type":"Multiple Choices","question":"What is the main advantage of using cloud software?","answer":"D) Files can be accessed from any computer with an internet connection.","options":["A) You can edit graphics easily.","B) You can manage databases efficiently.","C) You can work offline all the time.","D) Files can be accessed from any computer with an internet connection."]},{"numb":48,"type":"Multiple Choices","question":"Which of the following is a disadvantage of cloud software?","answer":"A) Online applications tend to run more slowly.","options":["A) Online applications tend to run more slowly.","B) It is always free to use.","C) It requires specialized hardware.","D) It does not support collaboration."]},{"numb":49,"type":"Multiple Choices","question":"Which of the following is a feature of presentation graphics software?","answer":"C) Creating slideshows with text, images, and multimedia.","options":["A) Editing database files.","B) Managing financial data.","C) Creating slideshows with text, images, and multimedia.","D) Creating spreadsheet formulas."]},{"numb":50,"type":"Multiple Choices","question":"Which software is commonly used for creating and presenting slideshows?","answer":"A) Microsoft PowerPoint","options":["A) Microsoft PowerPoint","B) CorelDRAW","C) Adobe Photoshop","D) QuickBooks"]}]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_007', 'Chapter 6 : Applications Software (2/2)', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"Which of the following best describes multimedia software?","answer":"B) Software that handles audio, video, and interactive content.","options":["A) Software that manages databases.","B) Software that handles audio, video, and interactive content.","C) Software that creates spreadsheets.","D) Software that edits text documents."]},{"numb":2,"type":"Multiple Choices","question":"Which of the following programs is an example of video editing software?","answer":"D) Apple iMovie","options":["A) Microsoft Excel","B) Microsoft Word","C) Microsoft Paint","D) Apple iMovie"]},{"numb":3,"type":"Multiple Choices","question":"Which software allows you to capture and edit sound files?","answer":"B) Audacity","options":["A) Microsoft Access","B) Audacity","C) Microsoft Excel","D) Google Slides"]},{"numb":4,"type":"Multiple Choices","question":"What is the main function of a media player?","answer":"D) To play audio and video files.","options":["A) To edit graphic designs.","B) To manage financial data.","C) To create databases.","D) To play audio and video files."]},{"numb":5,"type":"Multiple Choices","question":"Which of the following software is used to play multimedia content?","answer":"A) Windows Media Player","options":["A) Windows Media Player","B) Microsoft Word","C) Microsoft Excel","D) CorelDRAW"]},{"numb":6,"type":"Multiple Choices","question":"What is the purpose of desktop publishing software?","answer":"B) To design professional-quality printed materials.","options":["A) To create slideshows.","B) To design professional-quality printed materials.","C) To edit digital photos.","D) To manage large datasets."]},{"numb":7,"type":"Multiple Choices","question":"Which of the following programs is an example of desktop publishing software?","answer":"C) Adobe InDesign","options":["A) Microsoft Word","B) Google Docs","C) Adobe InDesign","D) Microsoft Excel"]},{"numb":8,"type":"Multiple Choices","question":"Which of the following software is most commonly used for photo editing?","answer":"A) Adobe Photoshop","options":["A) Adobe Photoshop","B) Microsoft PowerPoint","C) Microsoft Excel","D) Google Sheets"]},{"numb":9,"type":"Multiple Choices","question":"What is the primary function of sound editing software?","answer":"D) To capture, edit, and apply effects to audio files.","options":["A) To create financial reports.","B) To design web pages.","C) To write and format documents.","D) To capture, edit, and apply effects to audio files."]},{"numb":10,"type":"Multiple Choices","question":"Which software would you use to organize and edit video content for a presentation?","answer":"B) Adobe Premiere Pro","options":["A) Microsoft Excel","B) Adobe Premiere Pro","C) Google Slides","D) Microsoft PowerPoint"]},{"numb":11,"type":"Multiple Choices","question":"Which of the following is a key advantage of open-source software?","answer":"C) Typically more stable and secure","options":["A) Expensive","B) Closed access","C) Typically more stable and secure","D) Requires a subscription"]},{"numb":12,"type":"Multiple Choices","question":"Which of these is NOT an open-source operating system?","answer":"C) Windows","options":["A) Linux","B) Android","C) Windows","D) Ubuntu"]},{"numb":13,"type":"Multiple Choices","question":"Shareware is:","answer":"C) Distributed on the honor system","options":["A) Free for life","B) Software in the public domain","C) Distributed on the honor system","D) Always open-source"]},{"numb":14,"type":"Multiple Choices","question":"Desktop software is typically used on:","answer":"B) Personal computers","options":["A) Smartphones","B) Personal computers","C) Tablets only","D) None of the above"]},{"numb":15,"type":"Multiple Choices","question":"Which of these platforms commonly offers mobile apps?","answer":"B) Google Play Store","options":["A) Microsoft Store","B) Google Play Store","C) Ubuntu App Store","D) Amazon App Store"]},{"numb":16,"type":"Multiple Choices","question":"Mobile ticketing allows users to:","answer":"B) Download and use digital tickets for events","options":["A) Purchase physical tickets online","B) Download and use digital tickets for events","C) Print tickets from home","D) Access tickets only from desktop computers"]},{"numb":17,"type":"Multiple Choices","question":"Installed software must be:","answer":"B) Installed on the device before it can run","options":["A) Delivered via the cloud","B) Installed on the device before it can run","C) Purchased exclusively online","D) Available without installation"]},{"numb":18,"type":"Multiple Choices","question":"One potential disadvantage of cloud software is:","answer":"B) File size limits","options":["A) It is always free","B) File size limits","C) It never updates","D) No internet access is required"]},{"numb":19,"type":"Multiple Choices","question":"A software suite typically includes:","answer":"B) A collection of software programs bundled together","options":["A) Only word processing software","B) A collection of software programs bundled together","C) Only spreadsheet software","D) Only database software"]},{"numb":20,"type":"Multiple Choices","question":"Editing a document usually involves:","answer":"B) Changing the content of the document","options":["A) Changing the document''s software","B) Changing the content of the document","C) Installing new fonts","D) Creating a new user account"]},{"numb":21,"type":"Multiple Choices","question":"Which feature helps automatically move text to the next line when the end of the screen line is reached?","answer":"C) Word wrap","options":["A) Page formatting","B) Font size adjustment","C) Word wrap","D) Spell check"]},{"numb":22,"type":"Multiple Choices","question":"Paragraph formatting can include:","answer":"B) Line spacing and alignment","options":["A) Font style and size","B) Line spacing and alignment","C) Only table formatting","D) Adding hyperlinks"]},{"numb":23,"type":"Multiple Choices","question":"Which of the following is NOT a common word processing software program?","answer":"B) Adobe Photoshop","options":["A) Microsoft Word","B) Adobe Photoshop","C) Apple Pages","D) Corel WordPerfect"]},{"numb":24,"type":"Multiple Choices","question":"A spreadsheet organizes data into:","answer":"B) Cells, rows, and columns","options":["A) Pages and paragraphs","B) Cells, rows, and columns","C) Lines and spaces","D) None of the above"]},{"numb":25,"type":"Multiple Choices","question":"In a spreadsheet, a single spreadsheet document is known as a:","answer":"B) Worksheet","options":["A) Workbook","B) Worksheet","C) Table","D) Database"]},{"numb":26,"type":"Multiple Choices","question":"What-if analysis in a spreadsheet is used to:","answer":"B) Explore different scenarios by changing data in a formula","options":["A) Organize cells alphabetically","B) Explore different scenarios by changing data in a formula","C) Format cells based on conditions","D) Print data in a specific layout"]},{"numb":27,"type":"Multiple Choices","question":"A chart created from spreadsheet data will:","answer":"B) Change automatically if the data changes","options":["A) Be static and unchangeable","B) Change automatically if the data changes","C) Be exported as a new worksheet","D) Have no connection to the spreadsheet data"]},{"numb":28,"type":"Multiple Choices","question":"A database is defined as:","answer":"B) A collection of related data stored in an organized manner","options":["A) A collection of unrelated data","B) A collection of related data stored in an organized manner","C) An operating system for data","D) A method for formatting word documents"]},{"numb":29,"type":"Multiple Choices","question":"In a database, a single type of data (e.g., name, phone number) is stored in a:","answer":"C) Field","options":["A) Record","B) Table","C) Field","D) File"]},{"numb":30,"type":"Multiple Choices","question":"A collection of related records in a database is known as a:","answer":"D) Table","options":["A) Field","B) Query","C) Report","D) Table"]},{"numb":31,"type":"Multiple Choices","question":"A query in a database is used to:","answer":"B) Extract specific data based on criteria","options":["A) Delete records permanently","B) Extract specific data based on criteria","C) Format data for printing","D) Create graphics"]},{"numb":32,"type":"Multiple Choices","question":"Which database view is commonly used for data display and editing?","answer":"B) Datasheet View","options":["A) Slide Sorter View","B) Datasheet View","C) Layout View","D) None of the above"]},{"numb":33,"type":"Multiple Choices","question":"A slide in a presentation typically contains:","answer":"C) Multiple elements such as text, images, and videos","options":["A) Only text","B) Only charts","C) Multiple elements such as text, images, and videos","D) Only hyperlinks"]},{"numb":34,"type":"Multiple Choices","question":"Which software is commonly used for creating presentation slides?","answer":"A) Microsoft PowerPoint","options":["A) Microsoft PowerPoint","B) CorelDRAW","C) Adobe Illustrator","D) Corel QuattroPro"]},{"numb":35,"type":"Multiple Choices","question":"The Slide Sorter View in presentation software:","answer":"B) Displays all slides as thumbnails for easy rearranging","options":["A) Plays the slideshow automatically","B) Displays all slides as thumbnails for easy rearranging","C) Deletes slides automatically","D) Changes slide formatting"]},{"numb":36,"type":"Multiple Choices","question":"Slides in a presentation can contain hyperlinks that:","answer":"B) Link to web pages or other resources","options":["A) Link only to other slides","B) Link to web pages or other resources","C) Link to video files only","D) Link to the same document only"]},{"numb":37,"type":"Multiple Choices","question":"Presentation graphics programs can often generate:","answer":"C) Web pages or web page content","options":["A) Word documents","B) Audio files","C) Web pages or web page content","D) Database queries"]},{"numb":38,"type":"Multiple Choices","question":"Graphics software is commonly used for:","answer":"B) Creating or modifying images","options":["A) Editing audio files","B) Creating or modifying images","C) Managing databases","D) Writing reports"]},{"numb":39,"type":"Multiple Choices","question":"Image editing software is typically used for:","answer":"A) Correcting brightness and contrast in photos","options":["A) Correcting brightness and contrast in photos","B) Writing text documents","C) Designing database structures","D) Editing audio files"]},{"numb":40,"type":"Multiple Choices","question":"Which of the following is commonly used for audio editing?","answer":"B) Audacity","options":["A) Microsoft Word","B) Audacity","C) Excel","D) Adobe Photoshop"]},{"numb":41,"type":"Multiple Choices","question":"Video editing software is used for:","answer":"A) Modifying existing videos","options":["A) Modifying existing videos","B) Creating presentation slides","C) Managing spreadsheet data","D) Editing images"]},{"numb":42,"type":"Multiple Choices","question":"Which software is typically used for video editing and DVD authoring?","answer":"B) Apple iMovie","options":["A) Adobe Photoshop","B) Apple iMovie","C) Microsoft Word","D) Corel Painter"]},{"numb":43,"type":"Multiple Choices","question":"A media player software is used to:","answer":"B) Play audio and video files","options":["A) Play only image files","B) Play audio and video files","C) Edit video content","D) Design website banners"]},{"numb":44,"type":"Multiple Choices","question":"Desktop publishing software is commonly used for:","answer":"B) Creating professional print materials","options":["A) Writing code","B) Creating professional print materials","C) Editing audio files","D) Managing spreadsheets"]},{"numb":45,"type":"Multiple Choices","question":"Educational software is primarily used for:","answer":"A) Teaching and learning purposes","options":["A) Teaching and learning purposes","B) Creating images","C) Editing video content","D) None of the above"]},{"numb":46,"type":"Multiple Choices","question":"Project management software helps with:","answer":"B) Planning and organizing projects","options":["A) Creating multimedia content","B) Planning and organizing projects","C) Playing media files","D) Managing databases"]},{"numb":47,"type":"Multiple Choices","question":"Which software is used for remote access and collaboration?","answer":"C) Remote Desktop and TeamViewer","options":["A) Microsoft Word","B) Adobe Photoshop","C) Remote Desktop and TeamViewer","D) Microsoft PowerPoint"]},{"numb":48,"type":"Multiple Choices","question":"CAD software is commonly used for:","answer":"C) Designing buildings or mechanical components","options":["A) Video editing","B) Database management","C) Designing buildings or mechanical components","D) Writing text documents"]},{"numb":49,"type":"Multiple Choices","question":"Personal finance software helps users with:","answer":"B) Organizing personal budgets and expenses","options":["A) Managing spreadsheets","B) Organizing personal budgets and expenses","C) Creating graphics","D) Editing videos"]},{"numb":50,"type":"Multiple Choices","question":"Multimedia software is primarily used for:","answer":"C) Editing and playing audio and video files","options":["A) Creating reports","B) Writing code","C) Editing and playing audio and video files","D) Managing databases"]}]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_008', 'Chapter 7 : Computer Networks', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"What is the primary use of a Global Positioning System (GPS)?","answer":"B) To determine the exact geographic location of a receiver","options":["A) To communicate between devices","B) To determine the exact geographic location of a receiver","C) To transmit data over the internet","D) To connect personal devices"]},{"numb":2,"type":"Multiple Choices","question":"Which of the following is not a type of network topology?","answer":"D) Cycle","options":["A) Star","B) Bus","C) Ring","D) Cycle"]},{"numb":3,"type":"Multiple Choices","question":"What is the key difference between wired and wireless networks?","answer":"A) Wired networks use cables, wireless networks do not","options":["A) Wired networks use cables, wireless networks do not","B) Wired networks uses for home usage and wireless using for hacking","C) Wired networks are more secure than wireless networks","D) Wireless networks cannot be used in businesses"]},{"numb":4,"type":"Multiple Choices","question":"Which type of network covers a small geographic area such as a home or office?","answer":"C) LAN","options":["A) WAN","B) MAN","C) LAN","D) PAN"]},{"numb":5,"type":"Multiple Choices","question":"What does the term \"bandwidth\" refer to?","answer":"B) The amount of data that can be transferred in a given period of time","options":["A) The physical distance between two network nodes","B) The amount of data that can be transferred in a given period of time","C) The speed at which data travels between devices","D) The type of cables used in a network"]},{"numb":6,"type":"Multiple Choices","question":"Which protocol is responsible for ensuring the delivery of data over a network?","answer":"D) TCP","options":["A) IP","B) HTTP","C) FTP","D) TCP"]},{"numb":7,"type":"Multiple Choices","question":"What type of signal is used in conventional telephone systems? ","answer":"B) Analog ","options":["A) Digital ","B) Analog ","C) Radio ","D) Infrared "]},{"numb":8,"type":"Multiple Choices","question":"Which wireless standard is commonly used for short-range communication? ","answer":"B) Bluetooth ","options":["A) Wi-Fi ","B) Bluetooth ","C) Ethernet ","D) WiMAX "]},{"numb":9,"type":"Multiple Choices","question":"What does RFID stand for in monitoring systems? ","answer":"A) Radio Frequency Identification ","options":["A) Radio Frequency Identification ","B) Remote Frequency Information Device ","C) Rapid Frequency Identification ","D) Radio Frequency Interconnect Device"]},{"numb":10,"type":"Multiple Choices","question":"What type of network is designed to connect an individual''s personal devices?","answer":"C) PAN","options":["A) LAN","B) WAN","C) PAN","D) MAN"]},{"numb":11,"type":"Multiple Choices","question":"Which of the following is a characteristic of a peer-to-peer (P2P) network?","answer":"B) All computers work at the same functional level","options":["A) Central server is used","B) All computers work at the same functional level","C) It is more complicated than client-server networks","D) It requires a wired connection"]},{"numb":12,"type":"Multiple Choices","question":"Which type of data transmission sends data one bit at a time, one after another?","answer":"B) Serial","options":["A) Parallel","B) Serial","C) Isochronous","D) Asynchronous"]},{"numb":13,"type":"Multiple Choices","question":"Which transmission type uses a dedicated path for communication between sender and receiver?","answer":"B) Circuit-Switching","options":["A) Packet-Switching","B) Circuit-Switching","C) Broadcasting","D) Synchronous"]},{"numb":14,"type":"Multiple Choices","question":"What type of cable is used in fiber-optic networking media?","answer":"C) Transparent clear glass or plastic fibers","options":["A) Twisted-pair cable","B) Coaxial cable","C) Transparent clear glass or plastic fibers","D) Copper wire"]},{"numb":15,"type":"Multiple Choices","question":"Which networking media uses radio signals to transmit data?","answer":"B) Wireless Networking Media","options":["A) Wired Networking Media","B) Wireless Networking Media","C) Coaxial Cable","D) Fiber-Optic Cable"]},{"numb":16,"type":"Multiple Choices","question":"Which frequency is commonly used in wireless networking applications?","answer":"A) 900 MHz","options":["A) 900 MHz","B) 1500 MHz","C) 8000 MHz","D) 100 MHz"]},{"numb":17,"type":"Multiple Choices","question":"What is the primary advantage of a mesh network?","answer":"B) Multiple connections allow messages to take various paths","options":["A) Simple and cheap to implement","B) Multiple connections allow messages to take various paths","C) All devices are directly connected to a central device","D) Requires minimal maintenance"]},{"numb":18,"type":"Multiple Choices","question":"What is the maximum typical range for a Wi-Fi network?","answer":"C) 300 feet","options":["A) 100 miles","B) 50 miles","C) 300 feet","D) 1000 feet"]},{"numb":19,"type":"Multiple Choices","question":"Which wireless standard is designed for very fast short-range networking?","answer":"D) WiGig","options":["A) WiMAX","B) Wi-Fi","C) ZigBee","D) WiGig"]},{"numb":20,"type":"Multiple Choices","question":"Which type of Ethernet is most commonly used today?","answer":"B) Gigabit Ethernet","options":["A) Fast Ethernet","B) Gigabit Ethernet","C) 10 Gigabit Ethernet","D) 40 Gigabit Ethernet"]},{"numb":21,"type":"Multiple Choices","question":"Which type of network covers a city or county?","answer":"D) MAN","options":["A) PAN","B) LAN","C) WAN","D) MAN"]},{"numb":22,"type":"Multiple Choices","question":"What is a significant feature of a star network topology?","answer":"A) Devices connect to a central device or server","options":["A) Devices connect to a central device or server","B) All devices are directly connected to each other","C) Devices connect to a single central cable","D) All devices operate independently"]},{"numb":23,"type":"Multiple Choices","question":"What type of data transmission is used when data travels in both directions simultaneously?","answer":"B) Full-Duplex","options":["A) Half-Duplex","B) Full-Duplex","C) Simplex","D) Parallel"]},{"numb":24,"type":"Multiple Choices","question":"Which of the following describes Power over Ethernet (PoE)?","answer":"B) Allows electrical power to be sent along Ethernet cables","options":["A) Uses radio waves to transmit power and data","B) Allows electrical power to be sent along Ethernet cables","C) Requires a separate power cable for each device","D) Can only be used in wireless networks"]},{"numb":25,"type":"Multiple Choices","question":"Which networking hardware is used to connect a computer to a network?","answer":"C) Network Adapter","options":["A) Modem","B) Router","C) Network Adapter","D) Switch"]},{"numb":26,"type":"Multiple Choices","question":"What is the primary function of a network switch?","answer":"C) Connects devices within the same network and filters traffic","options":["A) Converts digital signals to analog","B) Routes data between different networks","C) Connects devices within the same network and filters traffic","D) Provides wireless connectivity"]},{"numb":27,"type":"Multiple Choices","question":"Which protocol is commonly used for email transmission?","answer":"C) SMTP","options":["A) HTTP","B) FTP","C) SMTP","D) SNMP"]},{"numb":28,"type":"Multiple Choices","question":"Which layer of the OSI model is responsible for end-to-end communication and error recovery?","answer":"C) Transport Layer","options":["A) Physical Layer","B) Data Link Layer","C) Transport Layer","D) Application Layer"]},{"numb":29,"type":"Multiple Choices","question":"What is a key characteristic of packet-switching networks?","answer":"B) Data is divided into packets and sent independently","options":["A) Uses a dedicated path between sender and receiver","B) Data is divided into packets and sent independently","C) Messages are sent in real-time without any delays","D) Data is transmitted in a continuous stream"]},{"numb":30,"type":"Multiple Choices","question":"Which of the following is a disadvantage of a bus network topology?","answer":"D) If the main cable fails, the entire network goes down","options":["A) Requires a lot of cabling","B) Difficult to troubleshoot","C) Limited by the number of connected devices","D) If the main cable fails, the entire network goes down"]},{"numb":31,"type":"Multiple Choices","question":"What does \"SSID\" stand for in wireless networking?","answer":"B) Service Set Identifier","options":["A) Secure Socket Internet Device","B) Service Set Identifier","C) Signal Strength Indicator","D) Secure Signal Identifier"]},{"numb":32,"type":"Multiple Choices","question":"What is the main purpose of a firewall in networking?","answer":"B) To filter and control network traffic based on security rules","options":["A) To amplify wireless signals","B) To filter and control network traffic based on security rules","C) To convert analog signals to digital","D) To connect different network segments"]},{"numb":33,"type":"Multiple Choices","question":"Which of the following is a key benefit of using a VPN (Virtual Private Network)?","answer":"B) Secure encrypted connection over a public network","options":["A) Increased data transfer speed","B) Secure encrypted connection over a public network","C) Simplified network configuration","D) Unrestricted access to all websites"]},{"numb":34,"type":"Multiple Choices","question":"What is the function of a Domain Name System (DNS)?","answer":"B) Resolves human-readable domain names into IP addresses","options":["A) Assigns IP addresses to devices","B) Resolves human-readable domain names into IP addresses","C) Encrypts data during transmission","D) Manages network traffic"]},{"numb":35,"type":"Multiple Choices","question":"What type of network is typically used by a single organization across multiple locations?","answer":"D) WAN","options":["A) PAN","B) LAN","C) MAN","D) WAN"]},{"numb":36,"type":"Multiple Choices","question":"Which of the following devices is used to regenerate and strengthen signals in a network?","answer":"C) Repeater","options":["A) Switch","B) Router","C) Repeater","D) Firewall"]},{"numb":37,"type":"Multiple Choices","question":"What does the acronym \"MAC\" stand for in networking?","answer":"A) Media Access Control","options":["A) Media Access Control","B) Multi-Access Channel","C) Master Access Control","D) Multiple Address Coding"]},{"numb":38,"type":"Multiple Choices","question":"In a client-server network, which device provides services to other devices?","answer":"B) Server","options":["A) Client","B) Server","C) Router","D) Switch"]},{"numb":39,"type":"Multiple Choices","question":"Which protocol is used for secure communication over a computer network?","answer":"C) SSL/TLS","options":["A) HTTP","B) FTP","C) SSL/TLS","D) POP3"]},{"numb":40,"type":"Multiple Choices","question":"What is the main purpose of a router in a network?","answer":"A) To connect multiple networks and route data between them","options":["A) To connect multiple networks and route data between them","B) To store data for future use","C) To convert digital signals into analog signals","D) To connect computers within the same network"]},{"numb":41,"type":"Multiple Choices","question":"What type of attack involves overwhelming a network or system with traffic to disrupt its normal function?","answer":"C) Denial of Service (DoS)","options":["A) Phishing","B) Spoofing","C) Denial of Service (DoS)","D) Man-in-the-Middle"]},{"numb":42,"type":"Multiple Choices","question":"Which type of wireless security protocol is considered the most secure?","answer":"D) WPA3","options":["A) WEP","B) WPA","C) WPA2","D) WPA3"]},{"numb":43,"type":"Multiple Choices","question":"What does \"latency\" refer to in networking?","answer":"C) The delay before a transfer of data begins","options":["A) The speed of data transmission","B) The amount of data that can be sent at once","C) The delay before a transfer of data begins","D) The security level of a network"]},{"numb":44,"type":"Multiple Choices","question":"What type of network typically requires a license for operation?","answer":"C) Cellular Network","options":["A) Wi-Fi","B) ZigBee","C) Cellular Network","D) Bluetooth"]},{"numb":45,"type":"Multiple Choices","question":"Which of the following is an example of an Internet of Things (IoT) device?","answer":"B) Smart thermostat","options":["A) Desktop computer","B) Smart thermostat","C) External hard drive","D) Network switch"]},{"numb":46,"type":"Multiple Choices","question":"What is the primary function of a proxy server?","answer":"C) To act as an intermediary for requests from clients seeking resources","options":["A) To store and retrieve web pages","B) To encrypt data during transmission","C) To act as an intermediary for requests from clients seeking resources","D) To provide power to network devices"]},{"numb":47,"type":"Multiple Choices","question":"What type of device is commonly used to extend the range of a wireless network?","answer":"D) Repeater","options":["A) Router","B) Access Point","C) Switch","D) Repeater"]},{"numb":48,"type":"Multiple Choices","question":"What is a \"hotspot\" in the context of wireless networking?","answer":"A) A location where Wi-Fi is accessible","options":["A) A location where Wi-Fi is accessible","B) A device that strengthens wireless signals","C) A tool for testing network speed","D) A secure connection point in a network"]},{"numb":49,"type":"Multiple Choices","question":"What does the term \"cloud computing\" refer to?","answer":"B) Storing and accessing data and programs over the internet","options":["A) Running applications in a local environment","B) Storing and accessing data and programs over the internet","C) Using a mainframe computer for large-scale processing","D) A method of data encryption"]},{"numb":50,"type":"Multiple Choices","question":"What is an example of a widely used file transfer protocol?","answer":"B) FTP","options":["A) HTTP","B) FTP","C) SMTP","D) IMAP"]}]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('CS_009', 'Chapter 13 : Program Dev & Programming Languages', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"What is the primary goal of procedural programming?","answer":"C) To separate a program into small modules","options":["A) To divide a program into objects","B) To create a loop structure","C) To separate a program into small modules","D) To combine all code into one large module"]},{"numb":2,"type":"Multiple Choices","question":"In procedural programming, what is a \"procedure call\"?","answer":"C) Locating specific tasks in procedures to be called by the main program","options":["A) A function that ends the program","B) A loop within the main program","C) Locating specific tasks in procedures to be called by the main program","D) An error handling routine"]},{"numb":3,"type":"Multiple Choices","question":"Which approach to program design involves breaking the program into small modules using a top-down design?","answer":"C) Structured Programming","options":["A) Object-Oriented Programming","B) Procedural Programming","C) Structured Programming","D) Adaptive Software Development"]},{"numb":4,"type":"Multiple Choices","question":"What is the main purpose of using variables in structured programming?","answer":"B) To store the current value of data items","options":["A) To call external functions","B) To store the current value of data items","C) To create user interfaces","D) To manage program flow"]},{"numb":5,"type":"Multiple Choices","question":"In Object-Oriented Programming (OOP), what is an \"instance\"?","answer":"B) A specific object in a class","options":["A) A group of objects","B) A specific object in a class","C) A method that performs an action","D) An attribute of an object"]},{"numb":6,"type":"Multiple Choices","question":"What describes an object''s data in OOP?","answer":"C) Attributes","options":["A) Methods","B) Variables","C) Attributes","D) Classes"]},{"numb":7,"type":"Multiple Choices","question":"What programming approach allows for functions to be developed and modified individually?","answer":"D) Aspect-Oriented Programming","options":["A) Object-Oriented Programming","B) Structured Programming","C) Agile Software Development","D) Aspect-Oriented Programming"]},{"numb":8,"type":"Multiple Choices","question":"Which development methodology focuses on adapting the program as it is being written?","answer":"A) Adaptive Software Development","options":["A) Adaptive Software Development","B) Waterfall Development","C) Structured Programming","D) Procedural Programming"]},{"numb":9,"type":"Multiple Choices","question":"What is the primary goal of Agile Software Development?","answer":"B) To create software quickly","options":["A) To create software slowly and accurately","B) To create software quickly","C) To develop software in isolation","D) To focus solely on the technical aspects of software"]},{"numb":10,"type":"Multiple Choices","question":"What is the first phase of the Program Development Life Cycle (PDLC)?","answer":"A) Problem Analysis","options":["A) Problem Analysis","B) Program Design","C) Coding","D) Testing"]},{"numb":11,"type":"Multiple Choices","question":"During the Problem Analysis phase of the PDLC, what is developed?","answer":"B) Program specifications","options":["A) Program code","B) Program specifications","C) Final software package","D) Debugging tools"]},{"numb":12,"type":"Multiple Choices","question":"What is a flowchart used for in the Program Development Life Cycle?","answer":"B) To graphically depict the steps a computer program will take","options":["A) To outline the logic of a program","B) To graphically depict the steps a computer program will take","C) To write code in a specific language","D) To manage program variables"]},{"numb":13,"type":"Multiple Choices","question":"What does pseudocode represent?","answer":"D) English-like statements outlining the logic of a program","options":["B) Flowchart symbols","B) Flowchart symbols","C) Data storage format","D) English-like statements outlining the logic of a program"]},{"numb":14,"type":"Multiple Choices","question":"Which of the following is a control structure in programming?","answer":"C) Sequence Control Structure","options":["A) Pseudocode","B) Flowchart","C) Sequence Control Structure","D) UML Model"]},{"numb":15,"type":"Multiple Choices","question":"What type of control structure repeats a series of statements until a particular condition is met?","answer":"C) Repetition Control Structure","options":["A) Sequence Control Structure","B) Selection Control Structure","C) Repetition Control Structure","D) Decision Control Structure"]},{"numb":16,"type":"Multiple Choices","question":"What principle should be followed to avoid infinite loops in program design?","answer":"A) One-Entry-Point/One-Exit-Point Rule","options":["A) One-Entry-Point/One-Exit-Point Rule","B) Use GOTO statements","C) Use flowcharts instead of pseudocode","D) Avoid using variables"]},{"numb":17,"type":"Multiple Choices","question":"What is the purpose of testing the design of a program?","answer":"B) To ensure the logic is correct","options":["A) To finalize the program specifications","B) To ensure the logic is correct","C) To compile the program code","D) To write the user manual"]},{"numb":18,"type":"Multiple Choices","question":"What is a major consideration when choosing a programming language?","answer":"D) Suitability to the application","options":["A) The operating system","B) The popularity of the language","C) The color of the code editor","D) Suitability to the application"]},{"numb":19,"type":"Multiple Choices","question":"What is source code?","answer":"C) The computer program before it is compiled","options":["A) The final executable program","B) The comments in a program","C) The computer program before it is compiled","D) The error messages generated during compilation"]},{"numb":20,"type":"Multiple Choices","question":"What is the purpose of coding standards?","answer":"B) To standardize programming and make it easier to maintain","options":["A) To make programs more difficult to read","B) To standardize programming and make it easier to maintain","C) To hide the logic from other programmers","D) To ensure compatibility with older systems"]},{"numb":21,"type":"Multiple Choices","question":"What is reusable code?","answer":"A) Code segments that can be used multiple times with minor modifications","options":["A) Code segments that can be used multiple times with minor modifications","B) Code that is error-prone and needs frequent updates","C) Code that is written in a low-level language","D) Code that is specific to one platform"]},{"numb":22,"type":"Multiple Choices","question":"What is the process of ensuring a program is free of errors and works as intended?","answer":"B) Debugging","options":["A) Coding","B) Debugging","C) Designing","D) Documenting"]},{"numb":23,"type":"Multiple Choices","question":"What is a compiler?","answer":"A) A language translator that converts an entire program into machine language before executing it","options":["A) A language translator that converts an entire program into machine language before executing it","B) A tool used for drawing flowcharts","C) A method to control program flow","D) A type of programming language"]},{"numb":24,"type":"Multiple Choices","question":"What is the role of an interpreter?","answer":"C) It translates one line of code at a time","options":["A) It compiles the entire program at once","B) It converts assembly language into machine language","C) It translates one line of code at a time","D) It manages memory allocation"]},{"numb":25,"type":"Multiple Choices","question":"What is a run-time error?","answer":"B) An error that occurs when the program is running","options":["A) An error in the source code that prevents compilation","B) An error that occurs when the program is running","C) A logic error that produces incorrect results","D) An error in the flowchart"]},{"numb":26,"type":"Multiple Choices","question":"What is an alpha test?","answer":"D) An internal on-site test","options":["A) An external test conducted by users","B) A test of the documentation quality","C) A test of the flowchart logic","D) An internal on-site test"]},{"numb":27,"type":"Multiple Choices","question":"What is the final phase of the Program Development Life Cycle?","answer":"C) Implementation and Maintenance","options":["A) Coding","B) Debugging","C) Implementation and Maintenance","D) Problem Analysis"]},{"numb":28,"type":"Multiple Choices","question":"What is Application Lifecycle Management (ALM)?","answer":"B) Tools for creating and managing an application during its entire lifecycle","options":["A) A method for writing code","B) Tools for creating and managing an application during its entire lifecycle","C) A type of programming language","D) A testing technique"]},{"numb":29,"type":"Multiple Choices","question":"What is the purpose of an Integrated Development Environment (IDE)?","answer":"D) To provide a set of programming tools for writing software applications","options":["A) To create flowcharts","B) To manage hardware resources","C) To translate code into machine language","D) To provide a set of programming tools for writing software applications"]},{"numb":30,"type":"Multiple Choices","question":"What is the role of an API in programming?","answer":"B) To help applications interface with a particular operating system","options":["A) To create user interfaces","B) To help applications interface with a particular operating system","C) To manage program flow","D) To test program code"]},{"numb":31,"type":"Multiple Choices","question":"What is machine language?","answer":"A) A language using 1s and 0s","options":["A) A language using 1s and 0s","B) A high-level programming language","C) An object-oriented language","D) A language designed for web development"]},{"numb":32,"type":"Multiple Choices","question":"Which generation of programming languages includes FORTRAN and COBOL?","answer":"C) Third generation","options":["A) First generation","B) Second generation","C) Third generation","D) Fourth generation"]},{"numb":33,"type":"Multiple Choices","question":"What is the main advantage of fourth-generation languages (4GLs)?","answer":"A) They are closer to natural languages and easier to work with","options":["A) They are closer to natural languages and easier to work with","B) They are faster to execute","C) They require less memory","D) They are machine-dependent"]},{"numb":34,"type":"Multiple Choices","question":"Which programming language is commonly used for scientific applications?","answer":"B) FORTRAN","options":["A) COBOL","B) FORTRAN","C) BASIC","D) Visual Basic"]},{"numb":35,"type":"Multiple Choices","question":"What is the main use of COBOL?","answer":"B) Business data processing","options":["A) Web development","B) Business data processing","C) Graphic design","D) Game development"]},{"numb":36,"type":"Multiple Choices","question":"What is a microprocessor?","answer":"C) The central processing unit (CPU) of a microcomputer","options":["A) A high-level programming language","B) A type of computer memory","C) The central processing unit (CPU) of a microcomputer","D) A tool used in software development"]},{"numb":37,"type":"Multiple Choices","question":"What is the function of an operating system?","answer":"B) To manage computer hardware and software resources","options":["A) To provide a way to write code","B) To manage computer hardware and software resources","C) To connect to the internet","D) To debug applications"]},{"numb":38,"type":"Multiple Choices","question":"What is a GUI?","answer":"B) Graphical User Interface","options":["A) General User Instruction","B) Graphical User Interface","C) Global Utility Interface","D) General Utility Interface"]},{"numb":39,"type":"Multiple Choices","question":"What is the purpose of system software?","answer":"D) All of the above","options":["A) To run application software","B) To manage system resources","C) To provide security","D) All of the above"]},{"numb":40,"type":"Multiple Choices","question":"What is the role of application software?","answer":"B) To perform specific tasks for users","options":["A) To manage the computer’s hardware","B) To perform specific tasks for users","C) To connect to other computers","D) To manage system security"]},{"numb":41,"type":"Multiple Choices","question":"What type of computer is known for handling large-scale data processing and transaction processing?","answer":"C) Mainframe","options":["A) Microcomputer","B) Minicomputer","C) Mainframe","D) Supercomputer"]},{"numb":42,"type":"Multiple Choices","question":"What is a supercomputer primarily used for?","answer":"C) Complex computations like weather forecasting","options":["A) Business data processing","B) General computing tasks","C) Complex computations like weather forecasting","D) Office applications"]},{"numb":43,"type":"Multiple Choices","question":"What is the primary function of a minicomputer?","answer":"D) Supporting small to medium-sized organizations","options":["A) General business applications","B) High-performance computing","C) Handling bulk data processing","D) Supporting small to medium-sized organizations"]},{"numb":44,"type":"Multiple Choices","question":"What is another name for microcomputers?","answer":"D) Minicomputers","options":["A) Mainframes","B) Personal Computers (PCs)","C) Supercomputers","D) Minicomputers"]},{"numb":45,"type":"Multiple Choices","question":"Which of the following is a characteristic of mainframe computers?","answer":"C) Used for bulk data processing","options":["A) High-level personal use","B) Cost-effective for small businesses","C) Used for bulk data processing","D) Portable and lightweight"]},{"numb":46,"type":"Multiple Choices","question":"What is the key feature of supercomputers?","answer":"B) High processing power for complex tasks","options":["A) Portability","B) High processing power for complex tasks","C) General office applications","D) Low cost"]},{"numb":47,"type":"Multiple Choices","question":"What is a central theme in the evolution of computing?","answer":"B) Transition from complex hardware to software-driven processes","options":["A) Increased reliance on manual data entry","B) Transition from complex hardware to software-driven processes","C) Elimination of all forms of computers","D) Focus on single-task machines"]},{"numb":48,"type":"Multiple Choices","question":"Which generation of computers is associated with microprocessors?","answer":"D) Fourth generation","options":["A) First generation","B) Second generation","C) Third generation","D) Fourth generation"]},{"numb":49,"type":"Multiple Choices","question":"Which of the following is a major function of an operating system?","answer":"A) Executing user applications","options":["A) Executing user applications","B) Writing code","C) Managing web servers","D) Handling graphics design"]},{"numb":50,"type":"Multiple Choices","question":"What is a significant trend in the evolution of software?","answer":"B) Increased focus on user-friendly interfaces","options":["A) Decreased complexity","B) Increased focus on user-friendly interfaces","C) Focus on hardware development","D) Standardization of code across all platforms"]}]'::jsonb, 'computing-data-sciences', 1, 'intro-computer-systems', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
