INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('DST_010', 'Review 2', 'OP', 50, '[{"numb":1,"type":"Multiple Choices","question":"Dimensionality reduction techniques are primarily used for:","options":["Data visualization","Data compression","Noise removal","All the mentioned"],"answer":"All the mentioned","image":null},{"numb":2,"type":"Multiple Choices","question":"Which of the following is an application of dimensionality reduction?","options":["Customer relationship management","Image retrieval","Face recognition","All the mentioned"],"answer":"All the mentioned","image":null},{"numb":3,"type":"Multiple Choices","question":"Image classification involves:","options":["Classifying unlabeled documents","Storing and retrieving documents efficiently","Removing noise from documents","None of the mentioned"],"answer":"None of the mentioned","image":null},{"numb":4,"type":"Multiple Choices","question":"Gene expression microarray analysis deals with:","options":["Classifying novel samples into disease types","Analyzing high-dimensional microarray data","Reducing noise in gene expression data","reducing the dimensionality","All the mentioned"],"answer":"All the mentioned","image":null},{"numb":5,"type":"Multiple Choices","question":"Feature selection differs from feature reduction in that it always produces","options":["all original features","a subset of original features","another features","three features only for visualization"],"answer":"a subset of original features","image":null},{"numb":6,"type":"Multiple Choices","question":"Which model of feature selection relies on a predetermined classification algorithm?","options":["Filter model","Wrapper model","MRMR model","Unsupervised model"],"answer":"Wrapper model","image":null},{"numb":7,"type":"Multiple Choices","question":"Principal Component Analysis (PCA) is used for:","options":["Data compression","Dimensionality reduction","Feature selection","Image retrieval"],"answer":"Dimensionality reduction","image":null},{"numb":8,"type":"Multiple Choices","question":"The MRMR feature selection algorithm aims to","options":["Maximize redundancy between features","Minimize relevance of target features","Maximize relevance and minimize redundancy","minimize the variance"],"answer":"Maximize relevance and minimize redundancy","image":null},{"numb":9,"type":"Multiple Choices","question":"Which library in Python can be used for PCA?","options":["NumPy","Pandas","Scikit-learn","Matplotlib"],"answer":"Scikit-learn","image":null},{"numb":10,"type":"Multiple Choices","question":"What is the purpose of standardizing features before applying PCA?","options":["To normalize the data","To remove outliers","to replace missing data","visualization"],"answer":"To normalize the data","image":null},{"numb":11,"type":"Multiple Choices","question":"Information gain is a measure used in:","options":["Wrapper model","Filter model","MRMR model","PCA"],"answer":"Filter model","image":null},{"numb":12,"type":"Multiple Choices","question":"What is a lambda function in Python?","options":["A built-in function","An anonymous function defined with the lambda keyword","A special type of recursive function","A function that can only be used once"],"answer":"An anonymous function defined with the lambda keyword","image":null},{"numb":13,"type":"Multiple Choices","question":"What is the correct syntax for a lambda function that adds two numbers, a and b?","options":["lambda a, b: a + b","lambda a + b","function (a, b): return a + b","(lambda (a, b): return a + b)"],"answer":"lambda a, b: a + b","image":null},{"numb":14,"type":"Multiple Choices","question":"How do you call a lambda function that multiplies two numbers?","options":["(lambda a, b: a * b)(5, 3)","lambda a, b: a * b(5, 3)","call(lambda a, b: a * b, 5, 3)","lambda(5, 3, a * b)"],"answer":"(lambda a, b: a * b)(5, 3)","image":null},{"numb":15,"type":"Multiple Choices","question":"If the test set is used to select and fine tune the parameters of the models, then it is called ……….","options":["training set","validation set","backup set","original set"],"answer":"validation set","image":null},{"numb":16,"type":"True or False","question":"The test set is a subset of the training set.","options":["True","False"],"answer":"False","image":null},{"numb":17,"type":"Multiple Choices","question":"In ______ the (classes) are predefined.","options":["Association rules.","Summarization.","Clustering","Classification"],"answer":"Classification","image":null},{"numb":18,"type":"True or False","question":"The number of classes is not known in clustering task","options":["True","False"],"answer":"True","image":null},{"numb":19,"type":"Multiple Choices","question":"In the image below, which would be the best value for k assuming that the algorithm you are using is k-Nearest Neighbor.","options":["3","10","20","50"],"answer":"10","image":"/quizzes/Data Science Tools/DST_Images/20.png"},{"numb":20,"type":"Multiple Choices","question":"Which of the following machine learning algorithm can be used for imputing missing values of both categorical and continuous variables?","options":["Linear Regression","KNN","Logistic Regression","kmeans"],"answer":"KNN","image":null},{"numb":21,"type":"Multiple Choices","question":"Which of the following statement is true about kNN algorithm?","options":["k-NN performs much better if all of the data have the same scale and density.","it struggles when the number of objects is very large","k-NN makes no assumptions about the functional form of the problem being solved","All the mentioned"],"answer":"All the mentioned","image":null},{"numb":22,"type":"Multiple Choices","question":"The process of training a predictive model with well-defined target values is known as (1)","options":["Unsupervised learning","Supervised learning","Model estimation","Model testing"],"answer":"Supervised learning","image":null},{"numb":23,"type":"Multiple Choices","question":"Which of the following transformation is called the z-score transformation","options":["(X-max(X))/(Max(X)-Min(X)","(X-Mean(X))/(Max(X)-Min(X))","(X-Mean(X))/Standard Deviation of X","Mean(X)/Max(X)"],"answer":"(X-Mean(X))/Standard Deviation of X","image":null},{"numb":24,"type":"Multiple Choices","question":"Which of the following is finally produced by Hierarchical Clustering?","options":["final estimate of cluster centroids","tree showing how close things are to each other","assignment of each point to clusters","all of the mentioned"],"answer":"tree showing how close things are to each other","image":null},{"numb":25,"type":"Multiple Choices","question":"……… method works by grouping data objects into predefined number of groups k, by computing k cluster centers in each iteration","options":["Hierarchical","K-Means","K-Medoids","None of the above"],"answer":"K-Means","image":null},{"numb":26,"type":"Multiple Choices","question":"Agglomerative is …… tree","options":["Top-Down","Bottom-Up","Both a & b","Hybrid"],"answer":"Bottom-Up","image":null},{"numb":27,"type":"Multiple Choices","question":"Divisive is …….. Tree","options":["Top-Down","Bottom-Up","Both a & b","Hybrid"],"answer":"Top-Down","image":null},{"numb":28,"type":"Multiple Choices","question":"Consider the distance between one cluster and another cluster to be equal to the shortest distance from any member of one cluster to any member of the other cluster.","options":["Single linkage","Complete linkage","Average linkage","None of the above"],"answer":"Single linkage","image":null},{"numb":29,"type":"Multiple Choices","question":"How can you avoid overfitting your model?","options":["Keep the model simple","removing some of the noise in the training data","Use cross-validation techniques","Use regularization techniques","All the mentioned"],"answer":"All the mentioned","image":null},{"numb":30,"type":"Multiple Choices","question":"Which of the following is true regarding Data Science?","options":["Concerned only with big data","Heavy focus on machine learning algorithms","multidisciplinary approach that combines principles and practices from the fields","Concerned with theories in statistics"],"answer":"multidisciplinary approach that combines principles and practices from the fields","image":null},{"numb":31,"type":"Multiple Choices","question":"Which of the following HTTP methods modifies a server''s state?","options":["response = requests.put(...)","response = requests.post(...)","response = requests.delete(...)","a ,b ,c"],"answer":"a ,b ,c","image":null},{"numb":32,"type":"Multiple Choices","question":"Which module in Python supports machine learning?","options":["BeautifulSoup","matplotlib","pandas","sklearn"],"answer":"sklearn","image":null},{"numb":33,"type":"Multiple Choices","question":"how many records (rows) will be in the dataframe df, before executing the 3rd line","options":["1","3","2","4"],"answer":"4","image":"/quizzes/Data Science Tools/DST_Images/IntelliJ_Plugin-main_cpp (6).png"},{"numb":34,"type":"Multiple Choices","question":"how many columns will be printed after excuting all the code?","options":["6","2","3","4"],"answer":"2","image":"/quizzes/Data Science Tools/DST_Images/IntelliJ_Plugin-main_cpp (6).png"},{"numb":35,"type":"Multiple Choices","question":"how many rows will be printed after excuting all the code?","options":["6","2","3","4"],"answer":"2","image":"/quizzes/Data Science Tools/DST_Images/IntelliJ_Plugin-main_cpp (6).png"},{"numb":36,"type":"Multiple Choices","question":"the dataframe df will be saved as","options":["text file","xml","html","word"],"answer":"text file","image":"/quizzes/Data Science Tools/DST_Images/IntelliJ_Plugin-main_cpp (6).png"},{"numb":37,"type":"Multiple Choices","question":"How is the _id field automatically created if not provided in MongoDB?","options":["Integer","Timestamp","ObjectId","AutoID"],"answer":"ObjectId","image":null},{"numb":38,"type":"Multiple Choices",