l},{"numb":47,"type":"Multiple Choices","question":"Executing print(list(filter(lambda x: x < 2, [-1,0,5,3])) in Python produces","options":["[-1,0]","[3,5]","[5,3]","7"],"answer":"[-1,0]","image":null},{"numb":48,"type":"Multiple Choices","question":"Executing print(functools.reduce(lambda x, y: x*y, [1,2,3,4])) in Python produces","options":["24","10","[1,3,6,10]","1"],"answer":"24","image":null},{"numb":49,"type":"Multiple Choices","question":"Which of the following database is not a relational database?","options":["Mongo","MySQL","Oracle","MS Access"],"answer":"Mongo","image":null},{"numb":50,"type":"Multiple Choices","question":"Which of the following library is used for data visualization?","options":["TensorFlow","Scrapy","Scikit Learn","seaborn"],"answer":"seaborn","image":null}]'::jsonb, 'computing-data-sciences', 2, 'data-science-tools-software', 'term2') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.department_slug, level_num = EXCLUDED.level_num, subject_id = EXCLUDED.subject_id, term = EXCLUDED.term;
