INSERT INTO public.quiz_department (code, name, duration, questions_count, questions, department_slug, level_num, subject_id, term) VALUES ('ECO_005', 'الفصل الخامس - التوازن في السوق', 'OP', 12, '[{"numb":1,"type":"True/False","question":"يترتب على انخفاض أسعار خدمات عوامل الإنتاج مع بقاء ظروف الطلب على حالها إلى زيادة كل من سعر وكمية التوازن","answer":"خطأ","options":["صح","خطأ"]},{"numb":2,"type":"True/False","question":"إذا تساوى السعر الفعلي مع سعر التوازن لسلعة البنزين فإن الفرق بين الكمية المطلوبة والمعروضة من البنزين يساوي صفر","answer":"صح","options":["صح","خطأ"]},{"numb":1,"type":"Multiple Choices","question":"عند سعر التوازن من سلعة ما فلابد وأن يكون","answer":"كل ما سبق","options":["لكمية المطلوبة تتساوى مع الكمية المعروضة","فائض الطلب أو فائض العرض يساوى صفر","الطلب الزائد يساوى صفر","كل ما سبق","لا شيء مما سبق"]},{"numb":2,"type":"Multiple Choices","question":"ذا كان الطلب والعرض شكلهما طبيعي، فعند أي سعر أقل من سعر التوازن ستكون الكمية","answer":"المعروضة اقل من الكمية المطاوبة ","options":["المعروضة أكبر من الكمية المطاوبة ","المعروضة اقل من الكمية المطاوبة ","المطلوبة أقل من الكمية المعروضة","لا شئ مما سبق"]},{"numb":3,"type":"Multiple Choices","question":"إذا كان الطلب والعرض شكلهما طبيعي، فعند أي سعر أكبر من سعر التوازن ستكون الكمية","answer":"المعروضة اقل من الكمية المطاوبة ","options":["المعروضة أكبر من الكمية المطاوبة ","المعروضة اقل من الكمية المطاوبة ","المطلوبة أقل من الكمية المعروضة","لا شئ مما سبق"]},{"numb":4,"type":"Multiple Choices","question":"ذا زاد الطلب والعرض على سلعة ما معأ، فإنه مع بقاء العوامل الأخرى على حالها لابد وأن","answer":"تزيد الكمية، ولكن الأثر غير محدد بالنسبة للسعر","options":["يزيد كل من السعر والكمية","يقل كل من السعر والكمية","يزيد السعر، ولكن الأثر غير محدد بالنسبة للكمية","تزيد الكمية، ولكن الأثر غير محدد بالنسبة للسعر"]},{"numb":5,"type":"Multiple Choices","question":" زيادة الطلب على سلعة ما مع بقاء ظروف العرض ثابتة","answer":"زيادة كل من سعر وكمية التوازن","options":["زيادة كل من سعر وكمية التوازن","انخفاض كل من سعر وكمية التوازن","زيادة كمية التوازن وانخفاض سعر التوازن","نقص كمية التوازن وزيادة سعر التوازن"]},{"numb":6,"type":"Multiple Choices","question":"نقص الطلب على سلعة ما مع بقاء ظروف العرض ثابتة يؤدى بصفة عامة إلى","answer":"انخفاض كل من سعر وكمية التوازن","options":["زيادة كل من سعر وكمية التوازن","انخفاض كل من سعر وكمية التوازن","زيادة كمية التوازن وانخفاض سعر التوازن","نقص كمية التوازن وزيادة سعر التوازن"]},{"numb":7,"type":"Multiple Choices","question":"يترتب على انخفاض أسعار خدمات عوامل الانتاج المستخدمة فى إنتاج سلعة ما مع ثبات العوامل الأخرى ما يلي","answer":"زيادة كمية التوازن وانخفاض سعر التوازن","options":["زيادة كمية التوازن مع ثبات سعر التوازن","زيادة سعر التوازن مع ثبات كمية التوازن","زيادة كمية التوازن وانخفاض سعر التوازن","زيادة سعر التوازن وانخفاض سعر التوازن"]},{"numb":8,"type":"Multiple Choices","question":"يترتب على ارتفاع أسعار خدمات عوامل الانتاج المستخدمة فى إنتاج سلعة ما مع ثبات العوامل الأخرى","answer":"زيادة سعر التوازن وانخفاض سعر التوازن","options":["زيادة كمية التوازن مع ثبات سعر التوازن","زيادة سعر التوازن مع ثبات كمية التوازن","زيادة كمية التوازن وانخفاض سعر التوازن","زيادة سعر التوازن وانخفاض سعر التوازن"]},{"numb":9,"type":"Multiple Choices","question":"سعر التوازن هو ذلك السعر الذي يتوافر عنده اتجاه عام","answer":"لإستمرار عدم تغير الاسعار","options":["لاستمرار ارتفاع الأسعار","لاستمرار هبوط الأسعار","لإستمرار تقلب الأسعار","لإستمرار عدم تغير الاسعار"]},{"numb":10,"type":"Multiple Choices","question":"زيادة الطلب والعرض معأ على سلعة ما بنفس النسبة يؤدى إلى","answer":"ثبات سعر التوازن و زيادة كمية التوازن","options":["ثبات سعر التوازن و زيادة كمية التوازن","ثبات سعر التوازن وانخفاض كمية التوازن","انخفاض سعر التوازن وزيادة كمية التوازن","زيادة سعر التوازن وانخفاض كمية التوازن"]}]'::jsonb, 'media-analytics', 2, 'university-elective-1-ma', 'term1') ON CONFLICT (code) DO UPDATE SET name = EXCLUDED.name, duration = EXCLUDED.duration, questions_count = EXCLUDED.questions_count, questions = EXCLUDED.questions, department_slug = EXCLUDED.d